const VIEWS = {};
const ACT = {};

function go(view, opts = {}) {
  if (!VIEWS[view]) view = 'today';
  const same = UI.view === view;
  if (UI.view === 'boards' && view !== 'boards') Board.unmount();
  if (UI.view === 'focus' && view !== 'focus' && !Timer.running) Spot.stop();
  UI.view = view;
  Object.assign(UI, opts);
  try { history.replaceState(null, '', '#' + view); } catch (_) {}
  App.render(!same);
  try { localStorage.setItem('pitwall.view', view); } catch (_) {}
}

const App = {
  render(scrollTop = false) {
    this.refreshChrome();
    const v = VIEWS[UI.view];
    const out = v.render();
    $('#view').innerHTML = `<div class="view${scrollTop ? ' enter' : ''}" data-v="${UI.view}">${out}</div>`;
    $('#topTitle').textContent = TITLES[UI.view];
    $('#topActions').innerHTML = v.actions ? v.actions() : '';
    if (scrollTop) $('#scroller').scrollTop = 0;
    v.mount && v.mount($('#view'));
  },
  /** re-render only if the user isn't mid-edit in this view */
  refresh() {
    const v = VIEWS[UI.view];
    if (v.live) { this.refreshChrome(); v.live(); return; }
    const sc = $('#scroller').scrollTop;
    this.render(); $('#scroller').scrollTop = sc;
  },
  remoteChanged() { applyTheme(); this.refresh(); },
  refreshChrome() { renderSidebar(); renderTabbar(); },
};

function navCount(id) {
  if (id === 'today') return tasksToday().length || '';
  if (id === 'tasks') return openTasks().length || '';
  if (id === 'notes') return Object.keys(S.notes).length || '';
  if (id === 'exams') return Exams.stats().planned.length || '';
  if (id === 'goals') return Game.daily().filter(q => q.done && !q.claimed).length || '';
  if (id === 'projects') return (S.projects || []).filter(p => p.status === 'active').length || '';
  if (id === 'habits') { const n = S.habits.filter(h => !Habits.done(h)).length; return n || ''; }
  if (id === 'trips') { const t = S.trips.find(x => x.from >= todayK() && dayDiff(todayK(), x.from) <= 14); return t ? dayDiff(todayK(), t.from) + ' g' : ''; }
  return '';
}
function navGroups() { const hid = S.profile.hidden || []; return NAV.map(g => ({ g: g.g, items: g.items.filter(([id]) => !hid.includes(id)) })).filter(g => g.items.length); }
