            const now = Object.fromEntries((heads || []).map(h => [h.id, +h.u]));
            const changed = Object.keys(now).filter(id => first || now[id] !== self.lastU[id]);
            const removed = first ? [] : Object.keys(self.lastU).filter(id => !(id in now));
            let rows = [];
            for (let i = 0; i < changed.length; i += 40) {
              const part = changed.slice(i, i + 40).map(x => `"${x.replace(/"/g, '')}"`).join(',');
              rows = rows.concat(await self.rest(`pitwall_docs?select=id,u,v&id=in.(${encodeURIComponent(part)})`) || []);
            }
            const docs = Object.keys(now).map(id => ({ id }));
            const ch = rows.map(r => ({ type: 'modified', doc: { id: r.id, data: () => ({ v: r.v, u: +r.u }) } })).concat(removed.map(id => ({ type: 'removed', doc: { id, data: () => undefined } })));
