/* ---------------- Evening wrap-up ---------------- */
function eveningCard() {
  const h = new Date().getHours(), t = todayK();
  let dismissed = null; try { dismissed = localStorage.getItem('pitwall.eve'); } catch (_) {}
  if (h < 18 || dismissed === t) return '';
  const d = S.game.days[t] || {}, open = S.tasks.filter(x => !x.done && x.due && x.due <= t), tom = itemsOn(addDK(t, 1)), habitsLeft = S.habits.filter(x => !Habits.done(x));
  const je = S.journal.e[t];
  return `<section class="card span-12" style="background:linear-gradient(135deg,color-mix(in srgb,var(--indigo) 14%,var(--surface)),var(--surface))">
    <div class="card-h"><h2>Chiudi la giornata</h2><button class="more" data-act="eveHide" aria-label="Nascondi per oggi">${ico('x', 'sm')}</button></div>
    <div style="display:flex;gap:24px;flex-wrap:wrap;margin-bottom:14px">${[[d.tasks || 0, 'promemoria fatti'], [fmtMin(d.focus || 0), 'di focus'], [`${S.habits.length - habitsLeft.length}/${S.habits.length}`, 'abitudini'], [`+${d.xp || 0}`, 'XP oggi']].filter((x, i) => i !== 2 || S.habits.length).map(([v, k]) => `<div class="stat"><span class="v" style="font-size:24px">${v}</span><span class="k">${k}</span></div>`).join('')}</div>
    <div class="grid cols-2" style="gap:12px">
      <div style="min-width:0">${open.length ? `<b style="font-size:15px">${open.length} ${open.length === 1 ? 'promemoria ancora aperto' : 'promemoria ancora aperti'}</b><div class="muted" style="font-size:13px;margin:2px 0 8px">${esc(open.slice(0, 3).map(x => x.title).join(' · '))}</div><button class="btn sm" data-act="eveMove">Sposta a domani</button>` : `<b style="font-size:15px;color:var(--green)">Hai chiuso tutti i promemoria di oggi</b>`}${habitsLeft.length ? `<div class="muted" style="font-size:13px;margin-top:8px">Mancano: ${esc(habitsLeft.map(x => x.name).join(', '))}</div>` : ''}</div>
      <div style="min-width:0"><b style="font-size:15px">Domani</b><div class="muted" style="font-size:13px;margin-top:2px">${tom.length ? esc(tom.slice(0, 4).map(x => `${x.s ? x.s + ' ' : ''}${x.title}`).join(' · ')) : 'Niente in agenda per ora.'}</div></div>
    </div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px">${je && (je.t || je.m) ? '' : `<button class="btn" data-act="eveJournal">${ico('heart', 'sm')}Scrivi nel diario</button>`}<button class="btn" data-act="evePlan" style="color:var(--purple)">${ico('spark', 'sm')}Prepara domani con il segretario</button></div></section>`;
}
ACT.eveHide = () => { try { localStorage.setItem('pitwall.eve', todayK()); } catch (_) {} App.refresh(); };
ACT.eveMove = () => { const t = todayK(), tm = addDK(t, 1); let n = 0; S.tasks.forEach(x => { if (!x.done && x.due && x.due <= t) { x.due = tm; n++; } }); save('tasks'); App.refresh(); Island.toast({ icon: 'cal', t: `${n} promemoria spostati a domani`, ms: 2000 }); };
