ACT.evePlan = () => Assistant.ask('Fai il punto della mia giornata di oggi in poche righe e preparami domani: guarda gli impegni, i promemoria aperti e gli esami vicini, e proponimi le 3 priorità e quando farle. Se ti dico ok, mettile in calendario.');

/* ---------------- Desk mode (always-on dashboard) ---------------- */
const Desk = {
  el: null, t: null, lock: null,
  open() {
    if (this.el) return;
    this.el = document.createElement('div'); this.el.className = 'desk'; document.body.appendChild(this.el);
    { const th = DESK_THEMES[S.profile.deskTheme || 'base']; if (th && th[2] && unlocked(th[1])) { this.el.style.background = th[2]; this.el.classList.add('themed'); } }
    this.paint(); this.t = setInterval(() => this.paint(), 15000);
    this.ti = setInterval(() => { const c = $('#deskClock'); if (c) c.textContent = nowHM(); const tc = $('#deskTimer'); if (tc) tc.textContent = Timer.label(); }, 1000);
    try { navigator.wakeLock && navigator.wakeLock.request('screen').then(l => this.lock = l).catch(() => {}); } catch (_) {}
    if (!IN_CLAUDE) try { document.documentElement.requestFullscreen && document.documentElement.requestFullscreen().catch(() => {}); } catch (_) {}
    if (!IN_CLAUDE && SPA.connected()) SPA.start();
  },
  close() {
    clearInterval(this.t); clearInterval(this.ti); this.el && this.el.remove(); this.el = null;
    try { this.lock && this.lock.release(); } catch (_) {} this.lock = null;
    try { document.fullscreenElement && document.exitFullscreen(); } catch (_) {}
  },
  paint() {
    if (!this.el) return;
    const t = todayK(), d = new Date(), its = itemsOn(t).filter(i => !i.allDay), nowM = d.getHours() * 60 + d.getMinutes();
    const cur = its.find(i => hm2m(i.s) <= nowM && hm2m(i.e) > nowM), next = its.find(i => hm2m(i.s) > nowM);
    const tk = tasksToday().slice(0, 6);
    const spi = !IN_CLAUDE && SPA.connected() && SPA.st && SPA.st.item, spn = IN_CLAUDE && Spot.now;
    this.el.innerHTML = `<button class="icon-btn desk-x" data-act="deskClose" aria-label="Esci">${ico('x')}</button>
      <div class="desk-l"><div class="desk-date">${fmtLong(t)}</div><div class="desk-clock num" id="deskClock">${nowHM()}</div>
        ${cur ? `<div class="desk-ev" style="--c:${catOf(cur.cat).c}"><small>Adesso</small><b>${esc(cur.title)}</b><span>fino alle ${cur.e}${cur.loc ? ' · ' + esc(cur.loc) : ''}</span></div>` : ''}
        ${next ? `<div class="desk-ev" style="--c:${catOf(next.cat).c}"><small>Tra ${fmtMin(hm2m(next.s) - nowM)}</small><b>${esc(next.title)}</b><span>${next.s}${next.loc ? ' · ' + esc(next.loc) : ''}</span></div>` : (!cur ? `<div class="desk-ev" style="--c:var(--green)"><small>Agenda</small><b>Nient'altro oggi</b></div>` : '')}</div>
      <div class="desk-r">
        <div class="desk-card"><div style="display:flex;align-items:center;gap:14px"><b class="num" id="deskTimer" style="font-size:44px;font-weight:300;letter-spacing:-.02em">${Timer.label()}</b><span class="muted" style="flex:1">${Timer.mode === 'focus' ? 'Focus' : 'Pausa'}${Timer.running ? '' : Timer.paused ? ' · in pausa' : ''}</span>${Timer.running ? `<button class="round pause" style="width:56px;height:56px" data-act="deskTimer">Pausa</button>` : `<button class="round go" style="width:56px;height:56px" data-act="deskTimer">Avvia</button>`}</div></div>
        ${spi ? `<div class="desk-card" style="display:flex;gap:12px;align-items:center">${SPA.img(((spi.album && spi.album.images) || [])[0]?.url, 52, 10)}<div style="flex:1;min-width:0"><b style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(spi.name)}</b><span class="muted" style="font-size:13px">${esc((spi.artists || []).map(a => a.name).join(', '))}</span></div><button class="icon-btn ghost" data-act="spaPrev" aria-label="Precedente" style="color:var(--label)">${ico('prev')}</button><button class="icon-btn" data-act="spaToggle" aria-label="Riproduci o pausa" style="background:var(--label);color:var(--bg)">${ico(SPA.playing() ? 'pause' : 'play')}</button><button class="icon-btn ghost" data-act="spaNext" aria-label="Successivo" style="color:var(--label)">${ico('next')}</button></div>` : spn ? `<div class="desk-card" style="display:flex;gap:12px;align-items:center"><span class="tile-ico" style="width:52px;height:52px;border-radius:10px;background:${spColor(spn.name)}">${ico('music')}</span><div style="min-width:0"><b>${esc(spn.name)}</b><div class="muted" style="font-size:13px">${esc(spn.who)}</div></div></div>` : ''}
        <div class="desk-card"><div class="eyebrow" style="margin-bottom:8px">Da fare oggi</div>${tk.length ? tk.map(x => `<div style="display:flex;gap:10px;align-items:center;padding:6px 0"><button class="check" data-act="toggleTask" data-id="${x.id}" aria-label="Completa"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></button><span style="font-size:16px">${esc(x.title)}</span></div>`).join('') : '<span class="muted">Tutto fatto.</span>'}</div>
        ${S.habits.length ? `<div class="desk-card" style="display:flex;gap:12px;flex-wrap:wrap">${S.habits.map(h => habitCheck(h, false)).join('')}</div>` : ''}
      </div>`;
    $$('[data-hab]', this.el).forEach(b => b.onclick = () => { Habits.toggle(b.dataset.hab); this.paint(); });
  },
};
ACT.desk = () => Desk.open();
ACT.deskClose = () => Desk.close();
ACT.deskTimer = () => { Timer.running ? Timer.pause() : Timer.start(); Desk.paint(); };
document.addEventListener('keydown', e => { if (e.key === 'Escape' && Desk.el) Desk.close(); });

/* ---------------- Notifications (web version) ---------------- */
const Notify = {
  ok() { return !IN_CLAUDE && 'Notification' in window && Notification.permission === 'granted' && S.profile.notify !== false; },
  async ask() {
    if (IN_CLAUDE || !('Notification' in window)) { Island.toast({ icon: 'bolt', c: 'var(--orange)', t: 'Notifiche non disponibili qui', s: 'Usa la versione web installata sulla schermata Home', ms: 3200 }); return false; }
    const r = await Notification.requestPermission(); S.profile.notify = r === 'granted'; save('profile'); App.refresh();
    if (r === 'granted') this.send('Notifiche attive', 'Ti avviso per eventi, esami e fine del timer.');
    return r === 'granted';
  },
  async send(title, body) {
    if (!this.ok()) return;
    try { const reg = navigator.serviceWorker && await navigator.serviceWorker.getRegistration(); if (reg) { reg.showNotification(title, { body, icon: 'icon-192.png', badge: 'icon-192.png', tag: title }); return; } } catch (_) {}
    try { new Notification(title, { body }); } catch (_) {}
  },
};
ACT.notifyOn = () => Notify.ask();

