Object.assign(ACCENTS, { mint: ['#00C7BE', '#63E6E2'], gold: ['#C69A00', '#FFD60A'], sunset: ['#FF5E3A', '#FF7A59'], aqua: ['#0090D8', '#4CC3FF'] });
const LOCKED_ACCENT = { mint: 2, gold: 6, sunset: 10, aqua: 18 };
const DESK_THEMES = { base: ['Standard', 0, ''], night: ['Notte', 4, 'linear-gradient(160deg,#0b1026,#1b1f3b 60%,#3a1c5c)'], aurora: ['Aurora', 8, 'linear-gradient(160deg,#03263a,#0b5d4f 55%,#5b2a86)'], ocean: ['Oceano', 14, 'linear-gradient(170deg,#001a33,#003f6b 60%,#0a7ea4)'], gold: ['Oro', 25, 'linear-gradient(160deg,#1a1205,#3b2a06 55%,#7a5a0c)'] };
const RINGS = { base: ['Standard', 0], aurora: ['Aurora', 7], fire: ['Fuoco', 16] };
