document.addEventListener('click', e => { const b = e.target.closest('[data-boss]'); if (!b) return; const x = S.exams.find(z => z.id === b.dataset.boss); const c = x && Boss.courseFor(x); c ? openCourse(c.id) : editExam(b.dataset.boss); });
/* count topic advances and simulations for weekly challenges + boss hits */
