    this.el = document.createElement('div'); this.el.className = 'reader';
    this.el.innerHTML = `<header class="reader-bar"><button class="btn plain" data-r="close">${ico('left', 'sm')}Fine</button><b class="reader-title">${esc(d.name)}</b><span class="tnum muted" id="rPage" style="font-size:13px"></span>
      <div class="reader-tools">${[['hand', 'hand', 'Sfoglia'], ['pen', 'pen', 'Penna'], ['hl', 'hl', 'Evidenziatore'], ['eraser', 'eraser', 'Gomma']].map(([t, i, l]) => `<button class="tool" data-rt="${t}" aria-label="${l}" title="${l}" style="width:38px;height:38px">${ico(i)}</button>`).join('')}<span class="pdiv"></span>${this.COLORS.map(c => `<button class="pcolor" data-rc="${c}" style="--c:${c === 'ink' ? 'var(--label)' : c};width:22px;height:22px" aria-label="Colore"></button>`).join('')}<span class="pdiv"></span><button class="icon-btn ghost" data-r="undo" aria-label="Annulla">${ico('undo')}</button><button class="icon-btn ghost" data-r="zout" aria-label="Riduci">−</button><button class="icon-btn ghost" data-r="zin" aria-label="Ingrandisci">+</button></div></header>
      <div class="reader-body" id="rBody"><div class="empty" style="margin-top:20vh"><span class="ai-orb" style="width:40px;height:40px"></span><b>Apro il documento…</b></div></div>`;
    document.body.appendChild(this.el);
    $$('[data-rt]', this.el).forEach(b => b.onclick = () => { if (b.dataset.rt === 'eraser' && this.tool === 'eraser') { this.ei = ((this.ei == null ? 1 : this.ei) + 1) % 3; Island.toast({ icon: 'eraser', t: ['Gomma piccola', 'Gomma media', 'Gomma grande'][this.ei], ms: 1200 }); } this.tool = b.dataset.rt; this.paintTools(); });
    $$('[data-rc]', this.el).forEach(b => b.onclick = () => { this.color = b.dataset.rc; if (this.tool === 'eraser' || this.tool === 'hand') this.tool = 'pen'; this.paintTools(); });
    $$('[data-r]', this.el).forEach(b => b.onclick = () => ({ close: () => this.close(), undo: () => this.undo(), zin: () => this.zoom(1.25), zout: () => this.zoom(.8) })[b.dataset.r]());
    this.paintTools();
