    anthropic: { n: 'Claude, con chiave API', s: 'A pagamento, a consumo. La qualità migliore.', key: 'https://console.anthropic.com/settings/keys', keyHint: 'Chiave Anthropic (sk-ant-…)', free: false, pick: [/sonnet/i, /haiku/i, /opus/i] },
