    if (a.task) { go('tasks'); setTimeout(() => editTask(a.task), 200); return; }
    if (a.open) { const [kind, id, k] = a.open.split(':'); if (kind === 'event') { go('calendar'); setTimeout(() => editEvent(id, {}, k), 200); return; } }
