  try { const reg = navigator.serviceWorker && await navigator.serviceWorker.getRegistration(); if (reg) { reg.showNotification(title, { body, icon: 'icon-192.png', badge: 'icon-192.png', tag: a ? a.key : title, data: a ? { key: a.key, open: a.open, task: a.task, ev: a.ev, k: a.k, view: a.view, title: a.title } : null, actions: a && (a.ev || a.task) ? [{ action: 'snooze', title: 'Posticipa 10 min' }, { action: 'open', title: 'Apri' }] : [] }); return; } } catch (_) {}
