    const score = d => { const n = lines.slice(0, 60).map(l => this.split(l, d).length); const many = n.filter(x => x > 2); if (!many.length) return 0; const mode = many.sort((a, b) => many.filter(v => v === a).length - many.filter(v => v === b).length).pop(); return many.filter(x => x === mode).length * Math.min(mode, 12); };
