    let a = +m[1], b = /^\d+$/.test(m[2]) ? +m[2] : ['gen', 'feb', 'mar', 'apr', 'mag', 'giu', 'lug', 'ago', 'set', 'ott', 'nov', 'dic'].indexOf(m[2].slice(0, 3).toLowerCase()) + 1 || ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'].indexOf(m[2].slice(0, 3).toLowerCase()) + 1, y = +m[3];
    if (y < 100) y += 2000; if (order === 'mdy' && /^\d+$/.test(m[2])) [a, b] = [b, a];
