    s = s.replace(/^(pagamento|pag\.?|acquisto|operazione)\s+(pos|carta|tramite carta|con carta|contactless|apple pay|google pay|bancomat)?\s*/i, '').replace(/\b(del|in data|data)\s+\d{1,2}[/.-]\d{1,2}([/.-]\d{2,4})?(\s+ore\s+\d{1,2}[:.]\d{2})?/gi, ' ').replace(/carta\s*(n\.?\s*)?[*x]+\s*\d+/gi, ' ').replace(/\b\d+[.,]\d{2}\s*(eur|euro)\b/gi, ' ').replace(/\b(eur|euro)\b/gi, ' ').replace(/\s{2,}/g, ' ').trim();
