          const j = await a.api(`${base}?${new URLSearchParams({ startDateTime: parseD(from).toISOString(), endDateTime: parseD(to).toISOString(), $top: '500', $select: 'subject,start,end,location,isAllDay,webLink,categories' })}`);
          for (const e of j.value || []) {
            if ((e.categories || []).includes('Orbita')) continue;
            const s = e.start.dateTime.slice(0, 16), en = e.end.dateTime.slice(0, 16);
            out.push({ src: a.aid, kind: 'ms', cat, label, id: a.aid + ':' + e.id, title: e.subject || '(senza titolo)', date: s.slice(0, 10), endDate: e.isAllDay ? addDK(en.slice(0, 10), -1) : null, allDay: !!e.isAllDay, start: e.isAllDay ? '' : s.slice(11, 16), end: e.isAllDay ? '' : en.slice(11, 16), loc: (e.location && e.location.displayName) || '', link: e.webLink });
          }
