  async req(path, opt = {}) {
    const c = this.conn(); if (!c) throw Object.assign(new Error('non collegato'), { code: 'nologin' });
    const go = async () => fetch(`${c.base}/rest/v1/${path}`, { ...opt, headers: { apikey: c.key, Authorization: 'Bearer ' + await this.token(), 'Content-Type': 'application/json', ...(opt.headers || {}) } });
    let r; try { r = await go(); } catch (_) { throw Object.assign(new Error('rete'), { code: 'offline' }); }
    if (r.status === 401) { if (c.own) this.own.sess.exp = 0; else Cloud.sess.exp = 0; r = await go(); }
    if (!r.ok) { const t = await r.text(); throw Object.assign(new Error(t.slice(0, 240)), { code: r.status === 404 || /PGRST205|does not exist|schema cache/i.test(t) ? 'nosql' : 'err' }); }
    const t = await r.text(); return t ? JSON.parse(t) : null;
  },
  async auth(url, key, email, pw, signup) {
    const r = await fetch(`${url.replace(/\/+$/, '')}/auth/v1/${signup ? 'signup' : 'token?grant_type=password'}`, { method: 'POST', headers: { apikey: key, 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password: pw }) });
    const j = await r.json().catch(() => ({})); if (!r.ok) { const m = String(j.msg || j.error_description || j.message || r.status); throw new Error(/invalid login/i.test(m) ? 'Email o password sbagliate' : /not confirmed/i.test(m) ? 'Conferma prima l\'email (apri il link che ti è arrivato), poi premi Accedi' : /already registered|already exists/i.test(m) ? 'Account già esistente: premi Accedi' : m); }
    if (!j.access_token) return 'confirm'; this.own = { url, key, sess: null }; this.setOwn(j); return 'in';
  },
