/* ---------- sonno e sveglia ---------- */
const Wake = {
  P() { return { goal: 8, prep: 60, ...(S.profile.wake || {}) }; },
  plan(k = addDK(todayK(), 1)) { const P = this.P(), its = itemsOn(k).filter(it => !it.allDay && it.s).sort((a, b) => a.s.localeCompare(b.s)), first = its[0]; if (!first) return null; const wake = Math.max(5 * 60, hm2m(first.s) - P.prep), bed = wake - P.goal * 60 - 15; return { first, wake: m2hm(wake), bed: m2hm((bed + 1440) % 1440), goal: P.goal }; },
};
TODAY_CARDS.wake = 'Sveglia di domani'; if (!TODAY_DEFAULT.includes('wake')) TODAY_DEFAULT.splice(2, 0, 'wake');
TODAY_EXTRA.wake = () => { if (new Date().getHours() < 18) return ''; const w = Wake.plan(); if (!w) return '';
  return `<section class="card span-6 wake-card"><div class="card-h"><h3>Domani</h3><button class="more" data-act="wakeSet">Regola${ico('right', 'sm')}</button></div><div class="wake-row"><div><small class="muted">A letto entro</small><b class="tnum">🌙 ${w.bed}</b></div><div><small class="muted">Sveglia</small><b class="tnum">⏰ ${w.wake}</b></div></div><p class="muted" style="margin:6px 0 0;font-size:13px">Primo impegno: ${esc(w.first.title)} alle ${w.first.s} · ${w.goal} ore di sonno</p></section>`; };
ACT.wakeSet = () => { const P = Wake.P(); let g = P.goal, p = P.prep;
  openSheet({ title: 'Sonno e sveglia', left: { label: 'Annulla' }, right: { label: 'Salva', act: s => { S.profile.wake = { goal: g, prep: p, remind: $('#wkR', s.el).getAttribute('aria-pressed') === 'true' }; save('profile'); s.close(); App.refresh(); } },
    body: `<div class="field"><span class="lbl">Ore di sonno che vuoi fare</span>${seg('wkg', [[7, '7 h'], [7.5, '7 h ½'], [8, '8 h'], [9, '9 h']], g)}</div><div class="field"><span class="lbl">Tempo per prepararti e arrivare</span>${seg('wkp', [[30, '30 min'], [45, '45 min'], [60, '1 h'], [90, '1 h ½'], [120, '2 h']], p)}</div><div class="list flat"><div class="row"><span class="grow"><div class="t">Avvisami quando è ora di andare a letto</div><div class="s">30 minuti prima, se domani hai un impegno presto</div></span>${toggleBtn('wkR', P.remind !== false)}</div></div><p class="muted" style="font-size:13px;margin:0">Per la sveglia vera usa l'app Orologio: Orbita ti dice l'orario giusto in base al primo impegno di domani.</p>`,
    onMount(el) { wireSeg(el, 'wkg', v => g = +v); wireSeg(el, 'wkp', v => p = +v); wireToggle($('#wkR', el), () => {}); } }); };

/* ---------- cosa ti fa stare bene ---------- */
const MoodX = {
  rows(days = 60) { const out = []; for (let i = 1; i <= days; i++) { const k = addDK(todayK(), -i), e = S.journal.e[k]; if (!e || !e.m) continue; const H = (S.health && S.health.days[k]) || {}; out.push({ k, m: +e.m, sleep: H.sleep ? +H.sleep.h : null, sport: (H.burn || []).length > 0, steps: +H.steps || 0, focus: ((S.game.days || {})[k] || {}).focus || 0, ev: itemsOn(k).filter(x => !x.allDay).length, wd: dowIdx(k) }); } return out; },
  facts() {
    const R = this.rows(); if (R.length < 6) return null; const avg = L => L.length ? L.reduce((s, r) => s + r.m, 0) / L.length : null, out = [];
    const cmp = (label, A, B, a, b) => { const x = avg(A), y = avg(B); if (x != null && y != null && A.length >= 2 && B.length >= 2 && Math.abs(x - y) >= 0.3) out.push({ d: x - y, t: x > y ? `Stai meglio ${a} (${x.toFixed(1)} contro ${y.toFixed(1)})` : `Stai meglio ${b} (${y.toFixed(1)} contro ${x.toFixed(1)})`, label }); };
    cmp('sonno', R.filter(r => r.sleep >= 7), R.filter(r => r.sleep != null && r.sleep < 7), 'quando dormi almeno 7 ore', 'quando dormi meno di 7 ore');
    cmp('sport', R.filter(r => r.sport), R.filter(r => !r.sport), 'nei giorni in cui ti alleni', 'nei giorni senza allenamento');
    cmp('passi', R.filter(r => r.steps >= 7000), R.filter(r => r.steps && r.steps < 7000), 'quando cammini di più (7000+ passi)', 'nei giorni con meno passi');
    cmp('focus', R.filter(r => r.focus >= 60), R.filter(r => r.focus < 60), 'quando fai almeno un\'ora di concentrazione', 'nei giorni più leggeri di studio');
    cmp('impegni', R.filter(r => r.ev >= 4), R.filter(r => r.ev <= 2), 'nelle giornate piene', 'nelle giornate con pochi impegni');
    const wd = Array.from({ length: 7 }, (_, i) => avg(R.filter(r => r.wd === i))), best = wd.indexOf(Math.max(...wd.filter(x => x != null))), worst = wd.indexOf(Math.min(...wd.filter(x => x != null)));
    return { n: R.length, avg: avg(R), out: out.sort((a, b) => Math.abs(b.d) - Math.abs(a.d)), best: wd[best] != null ? DOW[(best + 1) % 7] : null, worst: wd[worst] != null && worst !== best ? DOW[(worst + 1) % 7] : null };
  },
};
{ const oR = VIEWS.journal.render; VIEWS.journal.render = function () { const h = oR.call(this), F = MoodX.facts(); const card = F ? `<section class="card mx-card"><div class="card-h"><h3>Cosa ti fa stare bene</h3><span class="muted" style="font-size:13px">ultimi ${F.n} giorni con l'umore</span></div>${F.out.length ? `<div class="list flat" style="box-shadow:none;margin:0 -8px">${F.out.slice(0, 4).map(f => `<div class="row"><span style="font-size:20px">${{ sonno: '😴', sport: '🏃', passi: '👟', focus: '🎯', impegni: '📅' }[f.label]}</span><span class="grow t" style="font-size:15px">${f.t}</span></div>`).join('')}</div>` : '<p class="muted" style="margin:0;font-size:14px">Ancora nessuna differenza evidente: continua a segnare l\'umore.</p>'}${F.best ? `<p class="muted" style="margin:8px 0 0;font-size:13px">Il giorno migliore di solito è il <b>${F.best}</b>${F.worst ? `, il più difficile il <b>${F.worst}</b>` : ''}.</p>` : ''}</section>` : ''; if (!card) return h; const i = h.indexOf('</p>'); return i > 0 ? h.slice(0, i + 4) + card + h.slice(i + 4) : card + h; }; }

/* ---------- giornata pesante ---------- */
ACT.heavyDay = () => {
  const t = todayK(), open = S.tasks.filter(x => !x.done && x.due && x.due <= t).sort((a, b) => (b.prio || 0) - (a.prio || 0) || (a.due || '').localeCompare(b.due || '')), keep = new Set(open.slice(0, 3).map(x => x.id)), evs = itemsOn(t).filter(x => !x.allDay && x.s && x.kind === 'event');
  const sh = openSheet({ title: 'Giornata pesante', wide: true, left: { label: 'Annulla' }, right: { label: 'Alleggerisci', act: s => { let n = 0; for (const x of open) if (!keep.has(x.id)) { x.due = typeof Sleep !== 'undefined' && x.prio >= 2 ? addDK(t, 1) : addDK(t, x.prio >= 1 ? 2 : 4); x.time = null; n++; } save('tasks'); S.profile.heavy = t; save('profile'); s.close(); App.refresh(); Island.toast({ icon: 'check', c: 'var(--green)', t: 'Giornata alleggerita', s: n ? `${n} promemoria spostati nei prossimi giorni` : 'Hai già solo l\'essenziale', ms: 2600 }); } },
    body: `<p class="muted" style="margin:0">Respira. Tieni solo le 3 cose che contano oggi: il resto lo sposto io nei prossimi giorni (le più importanti a domani). Tocca per scegliere cosa tenere.</p>
      <div class="list">${open.map(x => `<button class="row" data-hv="${x.id}"><span class="check ${keep.has(x.id) ? 'on' : ''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></span><span class="grow"><div class="t">${esc(x.title)}</div><div class="s">${x.due < t ? 'in ritardo' : 'oggi'}${x.prio ? ' · ' + '!'.repeat(x.prio) : ''}</div></span><span class="pill" data-hvl>${keep.has(x.id) ? 'Oggi' : 'Sposto'}</span></button>`).join('') || '<div class="row"><span class="muted">Nessun promemoria per oggi 🎉</span></div>'}</div>
      ${evs.length ? `<div class="section-h" style="margin:4px 0 0">Impegni di oggi</div><div class="list">${evs.map(e => `<div class="row"><span class="tnum muted" style="width:46px">${e.s}</span><span class="grow t">${esc(e.title)}</span>${e.ev ? `<button class="btn sm plain" data-hvs="${e.id}">Rimanda</button>` : ''}</div>`).join('')}</div>` : ''}
      <button class="btn plain" id="hvF" style="align-self:flex-start">${ico('timer', 'sm')}Dopo, 25 minuti di concentrazione sulla prima</button>`,
    onMount(el) { $$('[data-hv]', el).forEach(b => b.onclick = () => { const id = b.dataset.hv; keep.has(id) ? keep.delete(id) : keep.add(id); b.querySelector('.check').classList.toggle('on', keep.has(id)); $('[data-hvl]', b).textContent = keep.has(id) ? 'Oggi' : 'Sposto'; });
      $$('[data-hvs]', el).forEach(b => b.onclick = () => { if (typeof ACT.snooze === 'function') ACT.snooze({ dataset: { id: b.dataset.hvs, kind: 'event' } }); else { const e = S.events.find(x => x.id === b.dataset.hvs); if (e) editEvent(e.id); } });
      $('#hvF', el).onclick = () => { $('[data-sh=right]', el.closest('.sheet') || el).click(); setTimeout(() => ACT.startFocus(), 400); }; } });
  return sh;
};
{ const oA = VIEWS.today.actions; VIEWS.today.actions = () => `<button class="btn sm" data-act="heavyDay" title="Oggi è troppo: tieni solo l'essenziale">😮‍💨<span class="hide-narrow">Giornata pesante</span></button>` + oA(); }

/* ---------- blocchi di tempo per la settimana ---------- */
ACT.planWeek = () => {
  const P = typeof Brief !== 'undefined' ? Brief.P() : { from: '09:00', to: '19:00' }, t = todayK(), days = Array.from({ length: 7 }, (_, i) => addDK(t, i));
  const cand = S.tasks.filter(x => !x.done && !x.time && (!x.due || x.due <= addDK(t, 6))).sort((a, b) => (a.due || '9').localeCompare(b.due || '9') || (b.prio || 0) - (a.prio || 0)).slice(0, 30);
  const plan = () => { const used = {}, out = []; for (const x of cand) { const min = +x.est || 45, start = x.due && x.due > t ? days.indexOf(x.due) : 0, order = [...days.slice(0, Math.max(1, (x.due ? days.indexOf(x.due) : 6) + 1))].map((k, i) => [k, i]); let placed = null;
      for (const [k] of (order.length ? order : [[t, 0]]).filter(([d]) => !(S.profile.heavy === t && d === t))) { const sl = freeSlots(k, P.from, P.to, used[k] || []).find(([a, b]) => b - a >= min); if (sl) { const a = Math.ceil(sl[0] / 15) * 15; if (a + min <= sl[1]) { placed = { k, a }; (used[k] ||= []).push([a, a + min + 10]); break; } } }
      out.push({ x, min, at: placed }); } return out; };
  let R = plan();
  const sh = openSheet({ title: 'Blocchi di tempo · 7 giorni', wide: true, left: { label: 'Annulla' }, right: { label: 'Metti in agenda', act: s => { let n = 0; for (const r of R) if (r.at && r.on !== false) { r.x.due = r.at.k; r.x.time = m2hm(r.at.a); r.x.est = r.min; n++; } save('tasks'); s.close(); App.refresh(); Island.toast({ icon: 'cal', c: 'var(--green)', t: `${n} blocchi in agenda`, s: 'Li vedi nel Calendario: trascinali se vuoi spostarli', ms: 2600 }); } },
    body: `<p class="muted" style="margin:0">Ho messo ogni promemoria nel primo spazio libero prima della sua scadenza (orario ${P.from}–${P.to}). Cambia la durata o togli quelli che non vuoi.</p><div id="pwL"></div>` });
  const paint = () => { const by = {}; for (const r of R) (by[r.at ? r.at.k : 'none'] ||= []).push(r);
    $('#pwL', sh.el).innerHTML = [...days, 'none'].filter(k => by[k]).map(k => `<div class="section-h">${k === 'none' ? 'Non c\'è spazio' : relDay(k, true)}</div><div class="list">${by[k].sort((a, b) => (a.at ? a.at.a : 0) - (b.at ? b.at.a : 0)).map(r => `<div class="row"><button class="check ${r.on !== false && r.at ? 'on' : ''}" data-pwo="${r.x.id}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></button><span class="tnum" style="width:92px;color:var(--accent)">${r.at ? `${m2hm(r.at.a)}–${m2hm(r.at.a + r.min)}` : '—'}</span><span class="grow t">${esc(r.x.title)}</span><select class="input" data-pwm="${r.x.id}" style="width:auto">${[15, 30, 45, 60, 90, 120, 180].map(m => `<option value="${m}" ${m === r.min ? 'selected' : ''}>${m < 60 ? m + ' min' : m / 60 + ' h'}</option>`).join('')}</select></div>`).join('')}</div>`).join('') || '<p class="muted">Nessun promemoria senza orario nei prossimi 7 giorni.</p>';
    $$('[data-pwo]', sh.el).forEach(b => b.onclick = () => { const r = R.find(z => z.x.id === b.dataset.pwo); r.on = r.on === false; paint(); });
    $$('[data-pwm]', sh.el).forEach(s => s.onchange = () => { cand.find(z => z.id === s.dataset.pwm).est = +s.value; const off = new Set(R.filter(z => z.on === false).map(z => z.x.id)); R = plan(); R.forEach(z => { if (off.has(z.x.id)) z.on = false; }); paint(); }); };
  paint(); return sh;
};
{ const oA = VIEWS.tasks.actions; VIEWS.tasks.actions = () => `<button class="btn sm" data-act="tplOpen" title="Modelli pronti">${ico('copy', 'sm')}<span class="hide-narrow">Modelli</span></button><button class="btn sm" data-act="planWeek" title="Metti i promemoria nell'agenda della settimana">${ico('cal', 'sm')}<span class="hide-narrow">Blocchi di tempo</span></button>` + oA(); }

/* ---------- modelli ---------- */
const TPL_BUILTIN = [
  { id: 'b-esame', name: 'Preparare un esame', emoji: '🎓', base: 'Data dell\'esame', items: [['Raccogliere appunti, libro e slide', -30], ['Fare il piano di studio', -29], ['Prima lettura di tutto il programma', -21], ['Esercizi e domande frequenti', -14], ['Ripasso completo', -7], ['Simulazione d\'esame', -3], ['Ripasso leggero e preparare documenti', -1]] },
  { id: 'b-trasloco', name: 'Trasloco', emoji: '📦', base: 'Giorno del trasloco', items: [['Chiedere preventivi ai traslochi / furgone', -30], ['Disdire o volturare luce, gas, internet', -21], ['Comprare scatole e nastro', -14], ['Cambio di residenza in Comune', -7], ['Imballare tutto tranne l\'essenziale', -3], ['Lettura contatori', 0], ['Aggiornare indirizzo (banca, lavoro, università)', 3]] },
  { id: 'b-viaggio', name: 'Partenza per un viaggio', emoji: '✈️', base: 'Giorno della partenza', items: [['Controllare documenti e scadenze', -21], ['Prenotare trasporti e alloggio', -20], ['Assicurazione viaggio', -10], ['Cambiare valuta / avvisare la banca', -5], ['Check-in online', -1], ['Fare la valigia', -1], ['Caricare power bank e scaricare mappe offline', -1]] },
  { id: 'b-lavoro', name: 'Primo giorno di lavoro', emoji: '💼', base: 'Primo giorno', items: [['Preparare documenti (IBAN, codice fiscale, contratto)', -7], ['Provare il tragitto', -3], ['Preparare i vestiti', -1], ['Salvare i contatti dei colleghi', 1], ['Fare il punto dopo la prima settimana', 7]] },
  { id: 'b-festa', name: 'Organizzare una festa', emoji: '🎉', base: 'Giorno della festa', items: [['Lista invitati', -21], ['Prenotare il locale o decidere dove', -20], ['Mandare gli inviti', -14], ['Confermare il numero di persone', -5], ['Spesa: cibo, bibite, decorazioni', -2], ['Preparare la playlist', -1], ['Ringraziare tutti', 1]] },
];
ACT.tplOpen = () => {
  const all = () => [...TPL_BUILTIN, ...S.tpls];
  const sh = openSheet({ title: 'Modelli pronti', wide: true, left: { label: 'Chiudi' }, right: { label: 'Nuovo', primary: false, act: () => tplEdit() }, body: `<div class="grid cols-2" id="tpL"></div>` });
  $('#tpL', sh.el).innerHTML = all().map(t => `<button class="card tp-card" data-tp="${t.id}"><span style="font-size:28px">${t.emoji}</span><b>${esc(t.name)}</b><small class="muted">${t.items.length} cose da fare · ${esc(t.base || 'data di partenza')}</small></button>`).join('');
  $$('[data-tp]', sh.el).forEach(b => b.onclick = () => tplApply(all().find(t => t.id === b.dataset.tp)));
};
function tplApply(t) { let base = addDK(todayK(), Math.max(0, -Math.min(0, ...t.items.map(i => i[1])))); const on = t.items.map(() => true);
  const sh = openSheet({ title: `${t.emoji} ${t.name}`, wide: true, left: { label: 'Annulla' }, right: { label: 'Crea', act: s => { const pj = $('#taP', s.el).getAttribute('aria-pressed') === 'true'; let proj = null; if (pj && Array.isArray(S.projects)) { proj = { id: uid(), name: t.name, title: t.name, color: '#007AFF', members: [], created: Date.now() }; S.projects.push(proj); save('projects'); } let n = 0; t.items.forEach(([title, off], k) => { if (!on[k]) return; let due = addDK(base, off); if (due < todayK()) due = todayK(); S.tasks.push({ id: uid(), title, due, prio: off >= -1 && off <= 0 ? 2 : 1, cat: null, done: false, created: Date.now(), tpl: t.id, ...(proj ? { project: proj.id } : {}) }); n++; }); save('tasks'); s.close(); Sheets.slice().forEach(x => x.close()); App.refresh(); Island.toast({ icon: 'list', c: 'var(--green)', t: `${n} promemoria creati`, s: t.name, ms: 2400, action: { label: 'Vedi', fn: () => go('tasks') } }); } },
    body: `<div class="field"><label for="taB">${esc(t.base || 'Data')}</label><input class="input" type="date" id="taB" value="${base}" style="max-width:200px"></div><div class="list" id="taL"></div>${Array.isArray(S.projects) ? `<div class="list flat"><div class="row"><span class="grow"><div class="t">Raggruppa in un nuovo progetto</div></span>${toggleBtn('taP', false)}</div></div>` : '<span id="taP" aria-pressed="false" hidden></span>'}` });
  const paint = () => { $('#taL', sh.el).innerHTML = t.items.map(([title, off], k) => { let d = addDK(base, off); const past = d < todayK(); return `<button class="row" data-ta="${k}"><span class="check ${on[k] ? 'on' : ''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></span><span class="grow"><div class="t">${esc(title)}</div><div class="s" style="${past ? 'color:var(--orange)' : ''}">${past ? 'già passato: lo metto oggi' : relDay(d, true)}</div></span></button>`; }).join(''); $$('[data-ta]', sh.el).forEach(b => b.onclick = () => { on[+b.dataset.ta] = !on[+b.dataset.ta]; paint(); }); };
  $('#taB', sh.el).onchange = e => { base = e.target.value || base; paint(); }; const tp = $('#taP', sh.el); if (tp && tp.tagName === 'BUTTON') wireToggle(tp, () => {}); paint(); }
function tplEdit(id) { const t = id ? S.tpls.find(x => x.id === id) : null;
  openSheet({ title: 'Nuovo modello', left: { label: 'Annulla' }, right: { label: 'Salva', act: s => { const n = $('#teN', s.el).value.trim(); if (!n) return; const items = $('#teI', s.el).value.split('\n').map(l => l.trim()).filter(Boolean).map(l => { const m = l.match(/^(.*?)\s*\(([+-]?\d+)\)\s*$/); return m ? [m[1], +m[2]] : [l, 0]; }); const o = t || { id: uid() }; Object.assign(o, { name: n, emoji: $('#teE', s.el).value.trim() || '📋', base: $('#teB', s.el).value.trim() || 'Data di riferimento', items }); if (!t) S.tpls.push(o); save('tpls'); s.close(); Sheets.slice().forEach(x => x.close()); ACT.tplOpen(); } },
    body: `<div style="display:flex;gap:8px"><input class="input" id="teE" value="📋" style="width:62px;font-size:22px;text-align:center"><input class="input" id="teN" placeholder="Nome (es. Iscrizione all'anno)" style="flex:1"></div><input class="input" id="teB" placeholder="La data di riferimento (es. Inizio corsi)"><div class="field"><span class="lbl">Cose da fare, una per riga. Tra parentesi i giorni rispetto alla data (−7 = una settimana prima)</span><textarea class="input" id="teI" rows="7" placeholder="Pagare la prima rata (-10)\nComprare i libri (-3)\nIscriversi agli appelli (20)"></textarea></div>` }); }

/* ---------- alerts ---------- */
{ const old = Alerts.list.bind(Alerts); Alerts.list = function (hours = 48) {
  const out = old(hours), now = Date.now(), win = (key, k, hm, title, body, view) => { const at = this.at(k, hm); if (!this.fired[key] && at >= now - 10 * 60e3 && at <= now + hours * 36e5) out.push({ key, at, title, body, view }); };
  for (let i = 0; i <= Math.ceil(hours / 24); i++) { const k = addDK(todayK(), i), d = parseD(k);
    for (const r of S.routines) if (r.on && !Rt.done(r, k)) win(`rt:${r.id}:${k}`, k, r.time, `${r.emoji} ${r.name}`, `${r.items.length} passi · tocca per iniziare`, 'habits');
    for (const c of S.contacts || []) { const nb = Contacts.nextBday(c, k); if (nb && nb.date === addDK(k, 7) && giftsOf(c).length) win(`gf:${c.id}:${k}`, k, '18:00', `🎁 Tra una settimana è il compleanno di ${Contacts.name(c)}`, `Hai ${giftsOf(c).length} ${giftsOf(c).length === 1 ? 'idea' : 'idee'} regalo: ${giftsOf(c).slice(0, 2).map(g => g.t).join(', ')}`, 'contacts'); }
    if (d.getDay() === 6) { const L = Touch.list().filter(x => x.late >= 0); if (L.length) win(`tc:${k}`, k, '11:00', '💬 Da sentire questa settimana', L.slice(0, 4).map(x => Contacts.name(x.c)).join(', '), 'contacts'); }
    const W = Wake.P(); if (W.remind !== false) { const w = Wake.plan(addDK(k, 1)); if (w && hm2m(w.bed) > 18 * 60) win(`wk:${k}`, k, m2hm(hm2m(w.bed) - 30), '🌙 Tra mezz\'ora a letto', `Domani ${w.first.title} alle ${w.first.s}: sveglia alle ${w.wake}`, 'today'); }
  }
  return out.sort((a, b) => a.at - b.at); }; }
Promise.resolve().then(() => { if (typeof Assistant === 'undefined') return; const oT = Assistant.tools.bind(Assistant); Assistant.tools = function () { const self = this; return oT().concat([
  { name: 'add_gift_idea', description: 'Salva un\'idea regalo per una persona della Rubrica.', inputSchema: { type: 'object', properties: { person: { type: 'string' }, idea: { type: 'string' }, price: { type: 'number' } }, required: ['person', 'idea'] }, execute(i) { const q = String(i.person).toLowerCase(), c = (S.contacts || []).find(x => Contacts.name(x).toLowerCase().includes(q)); if (!c) throw new Error('persona non trovata in Rubrica'); S.gifts.push({ id: uid(), who: c.id, t: String(i.idea), price: +i.price || null, d: todayK(), done: false }); save('gifts'); self.note('gift', 'Idea regalo salvata'); return { ok: true, per: Contacts.name(c) }; } },
  { name: 'lighten_today', description: 'Apre la modalità “giornata pesante” per tenere solo 3 cose oggi e spostare il resto.', inputSchema: { type: 'object', properties: {} }, execute() { setTimeout(() => ACT.heavyDay(), 300); return { ok: true }; } },
  { name: 'plan_week_blocks', description: 'Propone i blocchi di tempo della settimana mettendo i promemoria negli spazi liberi.', inputSchema: { type: 'object', properties: {} }, execute() { setTimeout(() => ACT.planWeek(), 300); return { ok: true }; } },
]); }; });

/* =========================================================
   STUDIO 3 — interrogazione orale con l'AI sugli appunti del
   corso, previsione del voto di laurea, mappe concettuali sulla
   Lavagna, studio insieme (pomodoro di gruppo negli spazi
   condivisi) e “Scrivi con l'AI” (email, lettere, CV).
   ========================================================= */
for (const k of ['orals']) if (!CORE.includes(k)) CORE.push(k);
S.orals ||= [];

/* ---------- material for a subject: notes + searchable documents ---------- */
function studyText(subject, max = 16000) {
  const s = String(subject || '').toLowerCase(), parts = [];
  for (const n of Object.values(S.notes)) if ((n.subject || '').toLowerCase() === s || (n.title || '').toLowerCase().includes(s)) parts.push(`# ${n.title || 'Nota'}\n${n.text || ''}`);
  for (const d of S.docs) if ((d.subject || '').toLowerCase() === s && S.dtx[d.id]) parts.push(`# ${d.name}\n${S.dtx[d.id].t}`);
  let t = parts.join('\n\n'); if (t.length > max) t = t.slice(0, max); return t;
}
/* ---------- interrogazione ---------- */
ACT.oralExam = el => oralExam(el && el.dataset && el.dataset.subj);
function oralExam(subj) {
  const subs = [...new Set([...(S.exams || []).filter(e => e.status !== 'passed').map(e => e.name), ...docSubjects(), ...Object.values(S.notes).map(n => n.subject).filter(Boolean)])].filter(Boolean);
  let subject = subj || subs[0] || '', level = 'normale', N = 5, qn = 0, hist = [], cur = null, busy = false;
  const sh = openSheet({ title: 'Interrogazione', wide: true, left: { label: 'Chiudi' }, body: `<div id="orB" style="display:flex;flex-direction:column;gap:12px"></div>` });
  const B = $('#orB', sh.el);
  const setup = () => { B.innerHTML = `<p class="muted" style="margin:0">Il segretario fa il professore: ti fa ${N} domande sugli appunti e sui PDF della materia, valuta ogni risposta e alla fine ti dà un voto e cosa ripassare.</p>
      <div class="field"><label for="orS">Materia</label><input class="input" id="orS" list="orL" value="${esc(subject)}" placeholder="Es. Analisi 1"><datalist id="orL">${subs.map(s => `<option value="${esc(s)}">`).join('')}</datalist></div>
      <div class="field"><span class="lbl">Difficoltà</span>${seg('orl', [['facile', 'Ripasso'], ['normale', 'Esame'], ['difficile', 'Professore severo']], level)}</div>
      <div class="field"><span class="lbl">Domande</span>${seg('orn', [[3, '3'], [5, '5'], [8, '8']], N)}</div>
      <p class="muted" style="margin:0;font-size:13px" id="orM"></p><button class="btn primary" id="orGo" style="align-self:flex-start">${ico('play', 'sm')}Inizia</button>`;
    const info = () => { const t = studyText($('#orS', B).value); $('#orM', B).textContent = t ? `Uso ${Math.round(t.length / 1000)}k caratteri dei tuoi appunti e documenti di “${$('#orS', B).value}”.` : 'Non trovo appunti con questo nome: farò domande generali sul programma tipico della materia.'; };
    $('#orS', B).oninput = info; info(); wireSeg(B, 'orl', v => level = v); wireSeg(B, 'orn', v => N = +v);
    $('#orGo', B).onclick = () => { subject = $('#orS', B).value.trim(); if (!subject) { $('#orS', B).focus(); return; } ask(); }; };
  const call = async p => { const s = await Cap.get('sample'); if (!s) { aiUnavailable(); throw new Error('no ai'); } return s.json(p, { cache: false }); };
  const ctx = () => { const t = studyText(subject); return `Materia: ${subject}. Livello: ${level} (università italiana).${t ? `\nMateriale dello studente (usa SOLO questo come riferimento quando possibile):\n${t}` : ''}\nDomande già fatte: ${hist.map(h => h.q).join(' | ') || 'nessuna'}.`; };
  const ask = async () => { if (busy) return; busy = true; B.innerHTML = `<div class="empty" style="padding:30px"><span class="ai-orb" style="width:40px;height:40px"></span><b>Il professore pensa a una domanda…</b></div>`;
    try { const r = await call(`${ctx()}\nFai la domanda numero ${qn + 1} di ${N} di un'interrogazione orale: una sola domanda chiara, diversa dalle precedenti, che si risponde a voce in 1-2 minuti. Rispondi solo con JSON {"q": domanda, "topic": argomento breve}.`); cur = { q: String(r.q || '').trim(), topic: String(r.topic || '') }; } catch (e) { busy = false; if (e.message !== 'no ai') aiError(e); setup(); return; }
    busy = false; qn++; paintQ(); };
  const paintQ = () => { B.innerHTML = `<div class="ck-prog">${Array.from({ length: N }, (_, j) => `<i class="${j < qn - 1 ? 'ok' : j === qn - 1 ? 'on' : ''}"></i>`).join('')}</div>
      <div class="or-q"><small>Domanda ${qn} di ${N}${cur.topic ? ' · ' + esc(cur.topic) : ''}</small><p>${esc(cur.q)}</p></div>
      <div style="display:flex;gap:6px;align-items:flex-start"><textarea class="input" id="orA" rows="5" placeholder="Rispondi come faresti all'esame (anche a voce: tocca il microfono)" style="flex:1"></textarea>${Dictate.btn('orA')}</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="orSend">Rispondi</button><button class="btn plain" id="orSkip">Non lo so</button></div>`;
    Dictate.wire(B); setTimeout(() => $('#orA', B)?.focus(), 60);
    $('#orSend', B).onclick = () => grade($('#orA', B).value.trim()); $('#orSkip', B).onclick = () => grade(''); };
  const grade = async a => { if (busy) return; busy = true; const btn = $('#orSend', B); if (btn) { btn.disabled = true; btn.textContent = 'Valuto…'; }
    let r; try { r = await call(`${ctx()}\nDomanda: ${cur.q}\nRisposta dello studente: ${a || '(non ha risposto)'}\nValuta come un professore ${level === 'difficile' ? 'severo' : 'giusto'}. Rispondi solo con JSON {"score": 0-10, "feedback": 2-3 frasi in italiano su cosa va bene e cosa manca, "ideal": la risposta ideale in 3-5 frasi}.`); } catch (e) { busy = false; aiError(e); paintQ(); return; }
    busy = false; const sc = Math.max(0, Math.min(10, +r.score || 0)); hist.push({ q: cur.q, topic: cur.topic, a, score: sc, fb: String(r.feedback || ''), ideal: String(r.ideal || '') });
    B.innerHTML = `<div class="or-q"><small>Domanda ${qn} di ${N}</small><p>${esc(cur.q)}</p></div><div class="or-score" style="--c:${sc >= 7 ? 'var(--green)' : sc >= 5 ? 'var(--orange)' : 'var(--red)'}"><b>${sc}/10</b><span>${esc(r.feedback || '')}</span></div><details ${sc < 6 ? 'open' : ''}><summary class="muted" style="cursor:pointer">Risposta ideale</summary><p style="line-height:1.55">${esc(r.ideal || '')}</p></details><button class="btn primary" id="orNext" style="align-self:flex-start">${qn < N ? 'Prossima domanda' : 'Vedi il voto'}</button>`;
    $('#orNext', B).onclick = () => qn < N ? ask() : finish(); };
  const finish = () => { const avg = hist.reduce((s, h) => s + h.score, 0) / hist.length, vote = Math.max(0, Math.round(avg * 3)), pass = vote >= 18, weak = hist.filter(h => h.score < 6);
    S.orals.push({ id: uid(), d: todayK(), subject, level, n: hist.length, vote, weak: weak.map(h => h.topic || h.q.slice(0, 60)) }); if (S.orals.length > 100) S.orals.splice(0, S.orals.length - 100); save('orals');
    Game.add(20 + (pass ? 20 : 0), 'Interrogazione: ' + subject, { icon: 'grad' }); if (vote >= 27) confetti(140);
    B.innerHTML = `<div class="or-final" style="--c:${vote >= 24 ? 'var(--green)' : pass ? 'var(--orange)' : 'var(--red)'}"><small>Il tuo voto</small><b>${vote > 30 ? '30 e lode' : vote < 18 ? 'Non sufficiente' : vote}</b><span>${esc(subject)} · ${hist.length} domande</span></div>
      ${weak.length ? `<div class="section-h" style="margin:0">Da ripassare</div><div class="list">${weak.map(h => `<div class="row"><span class="grow"><div class="t">${esc(h.topic || h.q)}</div><div class="s">${h.score}/10</div></span></div>`).join('')}</div><button class="btn" id="orT">${ico('list', 'sm')}Mettili nei Promemoria</button>` : '<p style="margin:0">Hai risposto bene a tutto. 👏</p>'}
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="orAgain">${ico('refresh', 'sm')}Un'altra interrogazione</button></div>`;
    const T = $('#orT', B); if (T) T.onclick = () => { for (const h of weak) S.tasks.push({ id: uid(), title: `Ripassare: ${h.topic || h.q.slice(0, 60)} (${subject})`, due: addDK(todayK(), 1), prio: 1, cat: 'studio', done: false, created: Date.now() }); save('tasks'); T.disabled = true; T.textContent = '✓ Aggiunti'; App.refresh(); };
    $('#orAgain', B).onclick = () => { qn = 0; hist = []; setup(); }; };
  setup(); return sh;
}
{ const oA = VIEWS.exams.actions; VIEWS.exams.actions = () => `<button class="btn sm" data-act="oralExam">${ico('mic', 'sm')}<span class="hide-narrow">Interrogami</span></button>` + oA(); }

/* ---------- voto di laurea ---------- */
const Grad = {
  P() { return { cfuTot: 180, thesis: 5, bonus: 0, ...(S.profile.grad || {}) }; },
  calc() { const st = Exams.stats(), P = this.P(), left = Math.max(0, P.cfuTot - st.cfu), base = st.w * 110 / 30, fin = base + P.thesis + P.bonus;
    const needBase = 110 - P.thesis - P.bonus, needAvg = needBase * 30 / 110, gradedTot = st.cfuG + left, needRest = left ? (needAvg * gradedTot - st.sum) / left : null;
    return { st, P, left, base, fin, needRest, lode: fin >= 113 }; },
};
{ const oR = VIEWS.exams.render, oM = VIEWS.exams.mount;
  VIEWS.exams.render = function () { const h = oR.call(this); if (!Exams.passed().length) return h; const G = Grad.calc(), f = Math.min(110, Math.round(G.fin));
    const card = `<section class="card grad-card"><div class="card-h"><h3>Voto di laurea previsto</h3><button class="more" id="grSet">Imposta${ico('right', 'sm')}</button></div>
      <div class="grad-row"><div class="grad-big"><b class="tnum">${f}${G.lode ? '<small>e lode?</small>' : ''}</b><span>/110</span></div><div class="inst-facts"><div><span class="muted">Base</span><b class="tnum">${fmt1(G.base)}</b></div><div><span class="muted">Tesi + bonus</span><b class="tnum">+${G.P.thesis + G.P.bonus}</b></div><div><span class="muted">CFU mancanti</span><b class="tnum">${G.left}</b></div></div></div>
      <p class="muted" style="margin:8px 0 0;font-size:14px">${G.left ? (G.needRest == null ? '' : G.needRest > 30 ? `Per arrivare a 110 servirebbe più di 30 di media negli esami che mancano: punta sui punti della tesi.` : G.needRest <= 18 ? `Sei già in linea per il 110: ti basta passare gli esami che mancano.` : `Per il 110 ti serve una media di <b style="color:var(--label)">${fmt1(G.needRest)}</b> negli esami che mancano (${G.left} CFU).`) : 'Hai tutti i CFU: manca solo la tesi.'} Punti di tesi e bonus cambiano da ateneo ad ateneo: controlla il regolamento del tuo corso.</p></section>`;
    const mk = '<div class="section-h">'; const i = h.indexOf(mk); return i >= 0 ? h.slice(0, i) + card + h.slice(i) : h + card; };
  VIEWS.exams.mount = function (root) { oM && oM.call(this, root); const b = $('#grSet', root); if (b) b.onclick = () => { const P = Grad.P();
    openSheet({ title: 'Voto di laurea', left: { label: 'Annulla' }, right: { label: 'Salva', act: s => { S.profile.grad = { cfuTot: +$('#grC', s.el).value || 180, thesis: +$('#grT', s.el).value || 0, bonus: +$('#grB', s.el).value || 0 }; save('profile'); s.close(); App.refresh(); } },
      body: `<div class="form-grid"><div class="field"><label for="grC">CFU totali del corso</label><input class="input" id="grC" type="number" value="${P.cfuTot}"><small class="muted">180 triennale, 120 magistrale, 300 ciclo unico</small></div><div class="field"><label for="grT">Punti per la tesi (previsti)</label><input class="input" id="grT" type="number" min="0" max="11" value="${P.thesis}"></div><div class="field"><label for="grB">Bonus (lodi, in corso, Erasmus…)</label><input class="input" id="grB" type="number" min="0" max="6" value="${P.bonus}"></div></div>` }); }; }; }

/* ---------- mappe concettuali sulla Lavagna ---------- */
{ const oDS = drawStroke; drawStroke = function (g, st, ink) { if (st.t !== 'txt') return oDS(g, st, ink); g.save(); g.fillStyle = st.c === 'ink' ? ink : st.c; g.font = `${st.b ? '600 ' : ''}${st.w || 16}px -apple-system, "Segoe UI", Inter, sans-serif`; g.textAlign = 'center'; g.textBaseline = 'middle'; const L = String(st.s || '').split('\n'); L.forEach((l, i) => g.fillText(l, st.p[0], st.p[1] + (i - (L.length - 1) / 2) * (st.w || 16) * 1.2)); g.restore(); }; }
