  wrap(t, n = 18) { const w = String(t).split(/\s+/), L = []; let cur = ''; for (const x of w) { if ((cur + ' ' + x).trim().length > n && cur) { L.push(cur); cur = x; } else cur = (cur + ' ' + x).trim(); } if (cur) L.push(cur); return L.slice(0, 3).join('\n'); },
