/* ---------- menu personalizzabile ---------- */
const NAVP = {
  studio: ['courses', 'exams', 'notes', 'boards', 'docs', 'thesis', 'lang'],
  lavoro: ['projects', 'hours', 'applies'],
  soldi: ['money', 'receipts', 'split', 'dues'],
  salute: ['health', 'meds', 'habits'],
  casa: ['shop', 'home', 'garage', 'ids', 'shared'],
  tempo: ['trips', 'journal', 'lists', 'recipes', 'parties', 'spots'],
  persone: ['messages', 'contacts'],
  crescita: ['year', 'review', 'goals', 'report', 'focus'],
};
const NAVA = { studio: ['🎓', 'Studio'], lavoro: ['💼', 'Lavoro'], soldi: ['💶', 'Soldi'], salute: ['💪', 'Salute e abitudini'], casa: ['🏠', 'Casa e documenti'], tempo: ['🎬', 'Tempo libero e viaggi'], persone: ['💬', 'Persone e messaggi'], crescita: ['🚀', 'Obiettivi e crescita'] };
{ const oNG = navGroups; navGroups = function () { const ord = S.profile.navOrder || []; return oNG().map(g => ({ ...g, items: g.items.slice().sort((a, b) => { const x = ord.indexOf(a[0]), y = ord.indexOf(b[0]); return (x < 0 ? 999 : x) - (y < 0 ? 999 : y); }) })); }; }
ACT.navEdit = () => {
  const all = NAV.map(g => ({ g: g.g, items: g.items.filter(([id]) => id !== 'today') })), P = S.profile; let hid = new Set(P.hidden || []), ord = [...(P.navOrder || [])];
  const sh = openSheet({ title: 'Personalizza il menu', wide: true, left: { label: 'Annulla' }, right: { label: 'Fine', act: s => { P.hidden = [...hid]; P.navOrder = ord; save('profile'); s.close(); App.render(); } }, body: `<div id="neB" style="display:flex;flex-direction:column;gap:12px"></div>` });
  const paint = () => { const B = $('#neB', sh.el), sortG = items => items.slice().sort((a, b) => { const x = ord.indexOf(a[0]), y = ord.indexOf(b[0]); return (x < 0 ? 999 : x) - (y < 0 ? 999 : y); });
    B.innerHTML = `<p class="muted" style="margin:0">Spegni quello che non usi e metti in alto quello che usi di più. Le sezioni nascoste restano raggiungibili dalla ricerca (⌘K o Ctrl+K).</p>
      <div class="chips"><button class="chip" data-np="all">Tutto acceso</button>${Object.entries(NAVA).map(([k, [e, n]]) => `<button class="chip" data-np="${k}">${e} Solo ${n.toLowerCase()}</button>`).join('')}</div>
      ${all.map(g => `<div class="section-h" style="margin:4px 0 0">${esc(g.g || 'In alto')}</div><div class="list">${sortG(g.items).map(([id, n, i], j, A) => `<div class="row"><span class="tile-ico" style="background:${hid.has(id) ? 'var(--gray)' : 'var(--accent)'}">${ico(i)}</span><span class="grow t" style="${hid.has(id) ? 'color:var(--label-3)' : ''}">${esc(n)}</span><button class="icon-btn" data-nu="${id}" ${j ? '' : 'disabled'} aria-label="Su">${ico('left', 'sm').replace('ico sm', 'ico sm rot90')}</button><button class="icon-btn" data-nd="${id}" ${j < A.length - 1 ? '' : 'disabled'} aria-label="Giù">${ico('right', 'sm').replace('ico sm', 'ico sm rot90')}</button>${toggleBtn('nt_' + id, !hid.has(id))}</div>`).join('')}</div>`).join('')}`;
    $$('[data-np]', B).forEach(b => b.onclick = () => { const k = b.dataset.np; if (k === 'all') hid = new Set(); else { const keep = new Set(['assistant', 'calendar', 'tasks', 'settings', 'account', ...NAVP[k]]); hid = new Set(all.flatMap(g => g.items.map(x => x[0])).filter(id => !keep.has(id))); } paint(); });
    all.forEach(g => g.items.forEach(([id]) => { const t = $('#nt_' + id, B); if (t) wireToggle(t, on => { on ? hid.delete(id) : hid.add(id); paint(); }); }));
    const move = (id, d) => { const g = all.find(x => x.items.some(i => i[0] === id)), L = sortG(g.items).map(x => x[0]), i = L.indexOf(id), j = i + d; if (j < 0 || j >= L.length) return; [L[i], L[j]] = [L[j], L[i]]; ord = [...ord.filter(x => !L.includes(x)), ...L]; paint(); };
    $$('[data-nu]', B).forEach(b => b.onclick = () => move(b.dataset.nu, -1)); $$('[data-nd]', B).forEach(b => b.onclick = () => move(b.dataset.nd, 1)); };
  paint(); return sh;
};
/* a small “Personalizza” link at the bottom of the sidebar */
