{ const oA = VIEWS.today.actions; VIEWS.today.actions = () => UI.todayDrag ? `<button class="btn primary sm" data-act="todayDragEnd">${ico('check', 'sm')}Fine</button>` : `<button class="btn sm" data-act="todayDrag" title="Riordina le schede trascinandole">${ico('grid', 'sm')}<span class="hide-narrow">Riordina</span></button>` + oA(); }
