  const sh = openSheet({ title: '🗑️ Cestino', wide: true, left: { label: 'Chiudi' }, right: { label: 'Svuota', primary: false, act: () => { if (!Trash.all().length) return; Trash.purge(); paint(); Island.toast({ icon: 'trash', t: 'Cestino svuotato', ms: 1600 }); } }, body: '<div id="trB" style="display:flex;flex-direction:column;gap:10px"></div>' });
