/* ---------- codice a barre in dispensa ---------- */
const ZXING = ['https://cdn.jsdelivr.net/npm/@zxing/library@0.21.3/umd/index.min.js', 'https://unpkg.com/@zxing/library@0.21.3/umd/index.min.js'];
/** camera barcode reader: native BarcodeDetector when present (Chrome, Edge, Android), otherwise ZXing (Safari, iPad, desktop) */
async function codeScanner(video, onCode, onMsg) {
  let stop = () => {};
  if ('BarcodeDetector' in window) { try { const det = new BarcodeDetector({ formats: ['ean_13', 'ean_8', 'upc_a', 'upc_e'] }); const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); video.srcObject = stream; video.hidden = false; await video.play(); let raf = 0, last = '';
      const loop = async () => { try { const L = await det.detect(video); if (L[0] && L[0].rawValue !== last) { last = L[0].rawValue; onCode(last); setTimeout(() => last = '', 2500); } } catch (_) {} raf = requestAnimationFrame(loop); }; loop();
      return () => { cancelAnimationFrame(raf); stream.getTracks().forEach(t => t.stop()); }; } catch (_) {} }
  if (!navigator.mediaDevices) { onMsg && onMsg('Fotocamera non disponibile: scrivi le cifre del codice.'); return stop; }
  onMsg && onMsg('Avvio la fotocamera…');
  for (const src of ZXING) { try { await loadScript(src); break; } catch (_) {} }
  if (!window.ZXing) { onMsg && onMsg('Lettore non disponibile offline: scrivi le cifre sotto il codice.'); return stop; }
  try { const H = new Map([[ZXing.DecodeHintType.POSSIBLE_FORMATS, [ZXing.BarcodeFormat.EAN_13, ZXing.BarcodeFormat.EAN_8, ZXing.BarcodeFormat.UPC_A, ZXing.BarcodeFormat.UPC_E]]]); const rd = new ZXing.BrowserMultiFormatReader(H); let last = '';
    video.hidden = false; await rd.decodeFromConstraints({ video: { facingMode: 'environment' } }, video, r => { if (r && r.getText() !== last) { last = r.getText(); onCode(last); setTimeout(() => last = '', 2500); } });
    onMsg && onMsg('Inquadra il codice a barre della confezione.'); return () => { try { rd.reset(); } catch (_) {} };
  } catch (e) { onMsg && onMsg('Non riesco ad aprire la fotocamera: consenti l\'accesso o scrivi le cifre.'); return stop; } }
async function offProduct(code) { const r = await fetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json?fields=product_name,product_name_it,generic_name_it,brands,quantity,categories_tags`); const j = await r.json(); const p = j && j.product; if (!p) return null; const name = (p.product_name_it || p.product_name || p.generic_name_it || '').trim(); if (!name) return null; return { name, brand: String(p.brands || '').split(',')[0].trim(), qty: p.quantity || '', frozen: (p.categories_tags || []).some(c => /frozen|surgel/.test(c)) }; }
ACT.pantryCode = () => { let stop = () => {}; const added = [];
  const sh = openSheet({ title: '📷 Codice a barre', wide: true, left: { label: 'Fine' }, onClose: () => { stop(); if (added.length) App.refresh(); },
    body: `<video id="pcV" playsinline muted style="width:100%;border-radius:16px;background:#000;aspect-ratio:4/3;object-fit:cover" hidden></video><p class="muted" style="margin:0;font-size:14px" id="pcM">Inquadra il codice a barre: aggiungo il prodotto alla dispensa. Puoi passarne tanti di fila.</p>
      <div style="display:flex;gap:8px"><input class="input" id="pcI" inputmode="numeric" placeholder="Oppure scrivi le cifre (es. 8076809513753)" style="flex:1"><button class="btn primary" id="pcGo">Cerca</button></div><div class="list" id="pcL" hidden></div>` });
  const M = t => { const m = $('#pcM', sh.el); if (m) m.textContent = t; };
  const look = async code => { code = String(code).replace(/\D/g, ''); if (code.length < 8) return; navigator.vibrate && navigator.vibrate(20); M('Cerco ' + code + '…'); let p = null; try { p = await offProduct(code); } catch (_) {}
    if (!p) { M('Non trovo questo prodotto: aggiungilo a mano con il nome.'); setTimeout(() => ACT.pantryAdd && ACT.pantryAdd(), 300); return; }
    const o = Pantry.add(p.brand && !p.name.toLowerCase().includes(p.brand.toLowerCase()) ? `${p.name} ${p.brand}` : p.name, { qty: p.qty, where: p.frozen ? 'freezer' : undefined }); if (o) { o.code = code; save('pantry'); added.push(o); Sound.done(); }
    M(`✓ ${o ? o.name : p.name} aggiunto${o && o.exp ? ' · scade ' + expLbl(o.exp).toLowerCase() : ''}`); const L = $('#pcL', sh.el); L.hidden = false; L.innerHTML = added.slice().reverse().map(x => `<div class="row"><span class="grow"><div class="t">${esc(x.name)}</div><div class="s">${esc([x.qty, x.where, x.exp ? 'scade ' + dIt(x.exp) : ''].filter(Boolean).join(' · '))}</div></span></div>`).join(''); };
  $('#pcGo', sh.el).onclick = () => look($('#pcI', sh.el).value); $('#pcI', sh.el).onkeydown = e => { if (e.key === 'Enter') look(e.target.value); };
  codeScanner($('#pcV', sh.el), look, M).then(s => { if (sh.closed) s(); else stop = s; });
  return sh; };
