    const md = (S.media || []).filter(m => m.status === 'done' && tsY(m.doneAt)), books = md.filter(m => m.type === 'book').length, films = md.filter(m => m.type === 'movie').length, series = md.filter(m => m.type === 'tv').length;
    let inc = 0, out = 0; for (const t of (S.money || {}).tx || []) { if (!inY(t.date) || (typeof Fin !== 'undefined' && Fin.isTr(t)) || t.loan) continue; if (t.amt > 0) inc += t.amt; else out -= t.amt; }
    const trips = (S.trips || []).filter(x => inY(x.from)), places = [...new Set(trips.map(x => x.place || x.title).filter(Boolean))];
