  $('.wr-sh', w).onclick = async e => { e.stopPropagation(); const blob = await Yr.image(R), f = new File([blob], `Il-mio-${R.y}-in-Orbita.png`, { type: 'image/png' }); try { if (navigator.canShare && navigator.canShare({ files: [f] })) { await navigator.share({ files: [f], title: `Il mio ${R.y} in Orbita` }); return; } } catch (_) { return; } saveBlob(blob, f.name); };
