    for (const e of S.exams) if (e.date === k && e.status === 'passed') P.push({ i: '🎓', t: `Hai superato ${e.name}`, s: e.grade ? `${e.grade}${e.lode ? ' e lode' : ''}` : 'Esame', go: 'exams' });
