    for (const x of S.trips || []) if (k >= x.from && k <= (x.to || x.from)) P.push({ i: '✈️', t: `Eri in viaggio: ${x.title || x.place}`, s: x.place || '', go: 'trips' });
    const done = S.tasks.filter(t => t.done && t.doneAt && dkey(new Date(t.doneAt)) === k); if (done.length >= 3) P.push({ i: '✅', t: `Hai chiuso ${done.length} cose`, s: done.slice(0, 3).map(t => t.title).join(', '), go: 'tasks' });
    for (const n of Object.values(S.notes)) if (n.created && dkey(new Date(n.created)) === k && n.title) P.push({ i: '📝', t: n.title, s: 'Nota scritta quel giorno', note: n.id });
