/* =========================================================
   DIETA — fotografa o carica il piano del nutrizionista (foto,
   PDF, Word o testo): l'AI lo trascrive giorno per giorno e
   pasto per pasto con grammi e valori. Poi Orbita ti dice cosa
   mangiare adesso, lo registri con un tocco nel diario di
   Salute, fa la lista della spesa della settimana e usa le
   calorie della dieta come obiettivo.
   ========================================================= */
const DMEAL = { colazione: ['Colazione', '☀️', 'colazione'], spuntino: ['Spuntino', '🍎', 'spuntini'], pranzo: ['Pranzo', '🍝', 'pranzo'], merenda: ['Merenda', '🥛', 'spuntini'], cena: ['Cena', '🌙', 'cena'] };
const DORD = ['colazione', 'spuntino', 'pranzo', 'merenda', 'cena'];
const MAMMOTH = 'https://cdn.jsdelivr.net/npm/mammoth@1.8.0/mammoth.browser.min.js';
const Diet = {
  D() { return (S.health || {}).diet || null; },
  /** which day of the plan applies to date k: by weekday when the plan has weekdays, otherwise rotating from the start date */
  dayIdx(k = todayK()) { const D = this.D(); if (!D || !D.days.length) return -1; const w = dowIdx(k) + 1, byDow = D.days.findIndex(d => +d.dow === w); if (byDow >= 0) return byDow; if (D.days.some(d => d.dow)) { const any = D.days.findIndex(d => !d.dow); return any >= 0 ? any : 0; } return ((dayDiff(D.start || todayK(), k) % D.days.length) + D.days.length) % D.days.length; },
  day(k = todayK()) { const i = this.dayIdx(k); return i < 0 ? null : this.D().days[i]; },
  nowMeal() { const h = new Date().getHours() + new Date().getMinutes() / 60, d = this.day(); if (!d) return null; const has = m => d.meals.find(x => x.meal === m); const pref = h < 10 ? ['colazione'] : h < 12 ? ['spuntino', 'pranzo'] : h < 15.5 ? ['pranzo'] : h < 18.5 ? ['merenda', 'cena'] : ['cena']; for (const m of pref) if (has(m)) return has(m); return d.meals.find(m => DORD.indexOf(m.meal) >= DORD.indexOf(pref[0])) || null; },
  key(di, mi, ii) { return `${di}.${mi}.${ii}`; },
  done(k = todayK()) { const D = this.D(); return new Set(((D && D.done) || {})[k] || []); },
  mark(k, keys) { const D = this.D(); D.done ||= {}; const s = new Set(D.done[k] || []); keys.forEach(x => s.add(x)); D.done[k] = [...s]; for (const d of Object.keys(D.done)) if (dayDiff(d, todayK()) > 40) delete D.done[d]; },
  food(it) { const k = +it.kcal; if (k > 0) return { name: it.n, kcal: k, p: +it.p || 0, c: +it.c || 0, f: +it.f || 0, src: 'diet', por: +it.g || 100 }; const m = typeof Health !== 'undefined' && Health.search ? Health.search(String(it.n).split(/[,(]/)[0])[0] : null; return m ? { ...m, name: it.n, src: 'diet' } : null; },
  /** log items of a meal into the Salute food diary */
  eat(di, mi, only = null, k = todayK()) { const D = this.D(), d = D.days[di], m = d.meals[mi], done = this.done(k), keys = []; let kcal = 0, n = 0;
    m.items.forEach((it, ii) => { const key = this.key(di, mi, ii); if (done.has(key) || (only != null && only !== ii)) return; const f = this.food(it), g = +it.g || 0; if (f && g) { Health.add(DMEAL[m.meal][2], f, g, k); kcal += f.kcal * g / 100; n++; } keys.push(key); });
    this.mark(k, keys); save('health'); return { n, kcal: Math.round(kcal), keys: keys.length }; },
  kcalDay(d) { return Math.round(d.meals.reduce((s, m) => s + m.items.reduce((a, it) => a + (+it.kcal || 0) * (+it.g || 0) / 100, 0), 0)); },
  shop(k0 = todayK(), n = 7) { const M = new Map(); for (let i = 0; i < n; i++) { const k = addDK(k0, i), d = this.day(k); if (!d) continue; for (const m of d.meals) for (const it of m.items) { const nm = String(it.n || '').trim(); if (!nm || /^acqua\b/i.test(nm)) continue; const key = nm.toLowerCase(); const o = M.get(key) || { name: nm, q: [], from: new Set() }; const q = String(it.q || '').trim(); o.q.push(/^\d+(?:[.,]\d+)?\s*(?:ml|l|litri?|g|gr|grammi|kg)\b/i.test(q) || /^\d+\s+(?!cucchiai)[a-zà-ù]+$/i.test(q) ? q : +it.g ? `${it.g} g` : q); o.from.add(DMEAL[m.meal][0]); M.set(key, o); } }
    const pan = (S.pantry || []).map(p => p.name.toLowerCase()); return [...M.values()].map(o => { const have = pan.some(p => p.includes(o.name.toLowerCase().split(/[ ,(]/)[0]) || o.name.toLowerCase().includes(p)), basic = PANTRY.test(o.name.trim()); return { name: o.name, qty: Menu.sumQty(o.q.filter(Boolean)), from: [...o.from], have, basic, on: !have && !basic }; }); },
};
async function dietRead(files, text) {
  const sample = await Cap.get('sample'); if (!sample) { aiUnavailable(); return null; }
  let images = [], txt = text || '';
  for (const f of files || []) {
    if (/pdf$/i.test(f.type) || /\.pdf$/i.test(f.name)) { const p = await readPdf(f, true); if ((p.text || '').trim().length > 200) txt += '\n' + p.text; else images.push(...(p.images || [])); }
    else if (/\.docx$/i.test(f.name)) { await loadScript(MAMMOTH); const r = await window.mammoth.extractRawText({ arrayBuffer: await f.arrayBuffer() }); txt += '\n' + r.value; }
    else if (/^text\//.test(f.type) || /\.(txt|md|csv)$/i.test(f.name)) txt += '\n' + await f.text();
    else if (/^image\//.test(f.type)) images.push(f);
  }
  if (!txt.trim() && !images.length) return null;
  const r = await sample.json(`Sei un nutrizionista italiano. ${images.length ? 'Nelle immagini c\'è' : 'Qui sotto c\'è'} un piano alimentare (dieta) scritto da un professionista. Trascrivilo FEDELMENTE, senza inventare alimenti: giorno per giorno e pasto per pasto. Se il piano è uguale ogni giorno usa un solo giorno con label "Tutti i giorni" e dow null. Se i giorni sono numerati (Giorno 1, 2…) usa dow null; se sono giorni della settimana metti dow (lunedì=1 … domenica=7). Per ogni alimento indica i grammi (stimali se la quantità è in pezzi, cucchiai o "a piacere") e i valori nutrizionali PER 100 g. Le alternative scritte nel piano (es. "oppure", "a scelta") vanno in "alt" come testo. Rispondi solo con JSON {"name": titolo breve della dieta, "kcal": calorie giornaliere indicate o stimate (numero), "notes": [indicazioni generali del piano, frasi brevi, massimo 8], "days": [{"label": string, "dow": numero o null, "meals": [{"meal": uno tra "colazione","spuntino","pranzo","merenda","cena", "label": nome del pasto come scritto, "items": [{"n": alimento, "q": quantità come scritta, "g": grammi (numero), "kcal": kcal per 100 g, "p": proteine per 100 g, "c": carboidrati per 100 g, "f": grassi per 100 g, "alt": [alternative]}]}]}]}.${txt.trim() ? '\n\n' + txt.slice(0, 16000) : ''}`, { images: images.slice(0, 6), cache: false });
  if (!r || !Array.isArray(r.days) || !r.days.length) return null;
  const days = r.days.slice(0, 14).map(d => ({ label: String(d.label || 'Giorno').slice(0, 40), dow: +d.dow >= 1 && +d.dow <= 7 ? +d.dow : null, meals: (d.meals || []).filter(m => m && Array.isArray(m.items) && m.items.length).map(m => ({ meal: DMEAL[m.meal] ? m.meal : /colaz/i.test(m.meal + m.label) ? 'colazione' : /pranz/i.test(m.meal + m.label) ? 'pranzo' : /cena/i.test(m.meal + m.label) ? 'cena' : /merend|pomerig/i.test(m.meal + m.label) ? 'merenda' : 'spuntino', label: String(m.label || '').slice(0, 40), items: m.items.filter(i => i && i.n).map(i => ({ n: String(i.n).slice(0, 80), q: String(i.q || '').slice(0, 40), g: Math.max(0, Math.round(+i.g || 0)), kcal: Math.round(+i.kcal || 0), p: +(+i.p || 0).toFixed(1), c: +(+i.c || 0).toFixed(1), f: +(+i.f || 0).toFixed(1), alt: (Array.isArray(i.alt) ? i.alt : []).map(String).filter(Boolean).slice(0, 4) })) })).sort((a, b) => DORD.indexOf(a.meal) - DORD.indexOf(b.meal)) })).filter(d => d.meals.length);
  if (!days.length) return null;
  return { name: String(r.name || 'La mia dieta').slice(0, 60), kcal: Math.round(+r.kcal || 0) || null, notes: (r.notes || []).map(String).slice(0, 8), days, start: todayK(), from: todayK(), done: {} };
}
