const MPRE = [['Revisione della caldaia', '🔥', 12], ['Controllo fumi caldaia', '🔥', 24], ['Pulizia filtri condizionatore', '❄️', 6], ['Sanificazione condizionatore', '❄️', 12], ['Batterie rilevatore di fumo', '🚨', 12], ['Filtro della lavatrice', '🧺', 3], ['Decalcificare la macchina del caffè', '☕', 2], ['Filtro della cappa', '🍳', 6], ['Sfiatare i termosifoni', '🌡️', 0, '10-15'], ['Gomme invernali', '❄️', 0, '11-01'], ['Gomme estive', '☀️', 0, '04-10'], ['Pulizia grondaie', '🏠', 12], ['Filtro acqua / caraffa', '💧', 1], ['Pulizia frigorifero', '🧊', 3], ['Controllo estintore', '🧯', 6], ['Cambio spazzolino', '🪥', 3]];
const Maint = {
  next(x) { if (x.date) { const y = new Date().getFullYear(); let k = `${y}-${x.date}`; if (x.last && x.last >= addDK(k, -60)) k = `${y + 1}-${x.date}`; else if (k < addDK(todayK(), -30) && (!x.last || x.last >= addDK(k, -60))) k = `${y + 1}-${x.date}`; return k; } const base = x.last || x.start || todayK(); return Dues.addMonths(base, +x.every || 12); },
  freq(x) { return x.date ? `ogni anno, il ${+x.date.slice(3)} ${MONTHS[+x.date.slice(0, 2) - 1]}` : +x.every === 1 ? 'ogni mese' : +x.every === 12 ? 'ogni anno' : +x.every === 24 ? 'ogni 2 anni' : `ogni ${x.every} mesi`; },
};
function maintEdit(id, pre = {}) { const x = id ? S.maint.find(z => z.id === id) : null, f = x || { name: pre.name || '', emoji: pre.emoji || '🔧', every: pre.every || 12, date: pre.date || '', last: '' }; let mode = f.date ? 'date' : 'every';
  openSheet({ title: x ? x.name : 'Manutenzione', left: { label: 'Annulla' }, right: { label: x ? 'Fine' : 'Aggiungi', act: s => { const g = k => $('#' + k, s.el).value.trim(); if (!g('mtN')) return; const o = x || { id: uid(), created: Date.now(), log: [] }; Object.assign(o, { name: g('mtN'), emoji: f.emoji, every: mode === 'every' ? Math.max(1, +g('mtE') || 12) : 0, date: mode === 'date' ? (g('mtD') || '01-01').slice(-5) : '', last: g('mtL') || null, start: o.start || todayK(), notes: g('mtNo') }); if (!x) S.maint.push(o); save('maint'); s.close(); App.refresh(); Island.toast({ icon: 'clock', c: 'var(--teal)', t: o.name, s: `Prossima: ${dIt(Maint.next(o))}`, ms: 2000 }); } },
    body: `<input class="input" id="mtN" value="${esc(f.name)}" placeholder="Es. revisione della caldaia">${seg('mtm', [['every', 'Ogni tot mesi'], ['date', 'Ogni anno in una data']], mode)}
      <div class="form-grid"><div class="field" id="mtEb" ${mode === 'every' ? '' : 'hidden'}><label for="mtE">Ogni quanti mesi</label><input class="input" type="number" id="mtE" min="1" value="${f.every || 12}"></div><div class="field" id="mtDb" ${mode === 'date' ? '' : 'hidden'}><label for="mtD">Data (ogni anno)</label><input class="input" type="date" id="mtD" value="${new Date().getFullYear()}-${f.date || '01-01'}"></div><div class="field"><label for="mtL">Ultima volta (se la ricordi)</label><input class="input" type="date" id="mtL" value="${f.last || ''}"></div></div>
      <textarea class="input" id="mtNo" rows="2" placeholder="Note (tecnico, numero, costo…)">${esc(x ? x.notes || '' : '')}</textarea>${x ? `<button class="btn danger plain" id="mtX" style="align-self:flex-start">${ico('trash', 'sm')}Elimina</button>` : ''}`,
    onMount(el, api) { wireSeg(el, 'mtm', v => { mode = v; $('#mtEb', el).hidden = v !== 'every'; $('#mtDb', el).hidden = v !== 'date'; }); const z = $('#mtX', el); if (z) z.onclick = () => { S.maint = S.maint.filter(q => q !== x); save('maint'); api.close(); App.refresh(); }; } }); }
