for (const k of ['quits', 'prices']) if (!CORE.includes(k)) CORE.push(k);
S.quits ||= []; S.prices ||= [];

/* ---------- smetti di… ---------- */
const QK = { fumo: ['Fumare', '🚭', 6, 'sigarette'], svapo: ['Svapare', '💨', 3, ''], zuccheri: ['Zuccheri e dolci', '🍬', 2, ''], alcol: ['Alcol', '🍷', 5, ''], social: ['Social', '📵', 0, ''], caffe: ['Caffè', '☕', 2, ''], bibite: ['Bibite gassate', '🥤', 2, ''], junk: ['Cibo spazzatura', '🍟', 6, ''], unghie: ['Mangiarsi le unghie', '💅', 0, ''], altro: ['Altro', '🎯', 0, ''] };
const QMIL = [[1, 'Il primo giorno'], [3, '3 giorni'], [7, 'Una settimana'], [14, 'Due settimane'], [30, 'Un mese'], [60, 'Due mesi'], [90, 'Tre mesi'], [180, 'Sei mesi'], [365, 'Un anno']];
const QFUMO = [[1 / 72, 'Dopo 20 minuti battito e pressione iniziano a scendere'], [0.5, 'Dopo 12 ore il monossido di carbonio nel sangue torna normale'], [2, 'Dopo 48 ore gusto e olfatto cominciano a migliorare'], [14, 'Tra 2 settimane e 3 mesi migliorano circolazione e respiro'], [270, 'Tra 1 e 9 mesi tosse e fiato corto diminuiscono'], [365, 'Dopo un anno il rischio di malattie cardiache si dimezza']];
const Quit = {
  since(q) { const L = (q.slips || []).slice().sort(); return Math.max(q.start, L.length && q.reset !== false ? new Date(L[L.length - 1]).getTime() : 0); },
  days(q) { return (Date.now() - this.since(q)) / 864e5; },
  saved(q) { return Math.max(0, (Date.now() - q.start) / 864e5 - (q.slips || []).length) * (+q.cost || 0); },
  best(q) { const P = [q.start, ...(q.slips || []).map(s => new Date(s).getTime()).sort()], g = P.slice(1).map((t, i) => t - P[i]); return Math.max(this.days(q), ...g.map(x => x / 864e5)); },
  next(q) { const d = this.days(q); return QMIL.find(m => m[0] > d) || null; },
};
function quitOpen(id) { const q = S.quits.find(x => x.id === id); if (!q) return quitEdit();
  const sh = openSheet({ title: `${QK[q.kind][1]} Smetti di… ${QK[q.kind][0].toLowerCase()}`, wide: true, left: { label: 'Chiudi' }, right: { label: 'Modifica', primary: false, act: s => { s.close(); quitEdit(q.id); } }, body: '<div id="qtB" style="display:flex;flex-direction:column;gap:12px"></div>' });
  let tk = 0; const paint = () => { const B = $('#qtB', sh.el); if (!B) return clearInterval(tk); const d = Quit.days(q), nx = Quit.next(q), ms = Date.now() - Quit.since(q), H = Math.floor(ms / 36e5) % 24, M = Math.floor(ms / 6e4) % 60;
    B.innerHTML = `<div class="qt-hero"><b class="tnum">${Math.floor(d)}</b><span>${Math.floor(d) === 1 ? 'giorno' : 'giorni'}<small class="tnum">${H} h ${M} min</small></span></div>
      <div class="dt-sum">${q.cost ? `<div><span class="muted">Risparmiati</span><b class="tnum" style="color:var(--green)">${eur(Quit.saved(q))}</b></div>` : ''}<div><span class="muted">Record</span><b class="tnum">${Math.floor(Quit.best(q))} g</b></div><div><span class="muted">Voglie superate</span><b class="tnum">${(q.cravings || []).length}</b></div></div>
      ${nx ? `<div class="qt-next"><span>Prossimo traguardo: <b>${nx[1]}</b></span><div class="qt-bar"><i style="width:${Math.min(100, d / nx[0] * 100)}%"></i></div></div>` : '<p style="margin:0">🏆 Hai superato tutti i traguardi. Incredibile.</p>'}
      ${q.why ? `<div class="card" style="background:var(--fill)"><small class="muted">Perché lo fai</small><p style="margin:2px 0 0;font-size:16px">“${esc(q.why)}”</p></div>` : ''}
      ${q.kind === 'fumo' ? `<div class="section-h" style="margin:4px 0 0">Cosa succede al corpo</div><div class="list flat">${QFUMO.map(([t, s]) => `<div class="row"><span class="check ${d >= t ? 'on' : ''}"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.2 4.2L19 7"/></svg></span><span class="grow" style="font-size:14px;${d >= t ? '' : 'color:var(--label-3)'}">${s}</span></div>`).join('')}</div><p class="muted" style="margin:0;font-size:12px">Fonte: tappe generali indicate dall'OMS. Per un aiuto concreto puoi chiamare il Telefono Verde contro il Fumo dell'ISS, 800 554 088.</p>` : ''}
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="qtV" style="background:var(--orange)">🆘 Ho una voglia</button><button class="btn plain" id="qtS">Ho ceduto</button></div>`;
    $('#qtV', B).onclick = () => cravingHelp(q, paint);
    $('#qtS', B).onclick = () => openSheet({ title: 'Succede', left: { label: 'Annulla' }, body: `<p style="margin:0">Una ricaduta non cancella i progressi: quello che hai fatto finora conta. Vuoi ripartire da zero col conteggio o continuare?</p><button class="btn primary" id="qsC">Continuo il conteggio</button><button class="btn" id="qsR">Riparto da oggi</button>`, onMount(el, api) { const go2 = reset => { (q.slips ||= []).push(new Date().toISOString()); q.reset = reset; save('quits'); api.close(); paint(); Island.toast({ icon: 'heart', c: 'var(--blue)', t: 'Ok, si riparte', s: 'Domani è un altro giorno', ms: 2200 }); }; $('#qsC', el).onclick = () => go2(false); $('#qsR', el).onclick = () => go2(true); } }); };
  paint(); tk = setInterval(paint, 30e3); return sh; }
function cravingHelp(q, after) { const tips = { fumo: ['Bevi un bicchiere d\'acqua fredda', 'Cammina 5 minuti, anche in casa', 'Mastica qualcosa: gomma, carota, frutta secca', 'Lavati i denti', 'Scrivi a qualcuno'], zuccheri: ['Bevi un bicchiere d\'acqua', 'Mangia un frutto o yogurt bianco', 'Esci a fare due passi', 'Lavati i denti'], alcol: ['Bevi acqua frizzante con limone', 'Chiama un amico', 'Cambia stanza o esci'], social: ['Metti il telefono in un\'altra stanza', 'Leggi 10 pagine', 'Fai 20 piegamenti'] }[q.kind] || ['Bevi un bicchiere d\'acqua', 'Fai due passi', 'Respira con me qui sopra'];
  let t = 0, tm = 0; const sh = openSheet({ title: '🆘 Passerà', left: { label: 'Chiudi' }, onClose: () => clearInterval(tm), body: `<p style="margin:0;text-align:center">Una voglia dura di solito pochi minuti. Respira con il cerchio per un minuto.</p><div class="qt-breath"><i id="qbC"></i><b id="qbT">Inspira</b></div><p class="muted tnum" id="qbS" style="text-align:center;margin:0">60 s</p>${q.why ? `<div class="card" style="background:var(--fill);text-align:center">“${esc(q.why)}”</div>` : ''}<div class="section-h" style="margin:0">Intanto</div><ul class="dt-notes">${tips.map(x => `<li>${esc(x)}</li>`).join('')}</ul><button class="btn primary" id="qbOk">💪 Passata!</button>` });
  const el = sh.el, C = $('#qbC', el), T = $('#qbT', el); tm = setInterval(() => { t++; const ph = t % 10; T.textContent = ph < 4 ? 'Inspira' : ph < 6 ? 'Trattieni' : 'Espira'; C.style.transform = `scale(${ph < 4 ? .6 + ph * .1 : ph < 6 ? 1 : 1 - (ph - 6) * .1})`; $('#qbS', el).textContent = t < 60 ? `${60 - t} s` : 'Bravo, ce l\'hai fatta'; if (t === 60) { navigator.vibrate && navigator.vibrate([60, 60, 60]); } }, 1000);
  $('#qbOk', el).onclick = () => { (q.cravings ||= []).push(Date.now()); save('quits'); sh.close(); Sound.done(); Game.add(10, 'Voglia superata', { icon: 'heart' }); after && after(); }; }
function quitEdit(id) { const q = id ? S.quits.find(x => x.id === id) : null; let kind = q ? q.kind : 'fumo';
  openSheet({ title: q ? 'Modifica' : 'Smetti di…', left: { label: 'Annulla' }, right: { label: q ? 'Fine' : 'Inizia', act: s => { const g = k => $('#' + k, s.el).value.trim(); const o = q || { id: uid(), created: Date.now(), slips: [], cravings: [] }; const st = g('qtD') ? new Date(g('qtD')).getTime() : Date.now(); Object.assign(o, { kind, start: q && !g('qtD') ? q.start : st, cost: parseFloat(g('qtC').replace(',', '.')) || 0, why: g('qtW'), label: kind === 'altro' ? g('qtL') : '' }); if (!q) S.quits.push(o); save('quits'); s.close(); App.refresh(); quitOpen(o.id); } },
    body: `<div class="chips">${Object.entries(QK).map(([k, v]) => `<button type="button" class="chip" data-seg="qtk" data-v="${k}" aria-pressed="${k === kind}">${v[1]} ${v[0]}</button>`).join('')}</div><input class="input" id="qtL" placeholder="Cosa (se “Altro”)" value="${esc(q && q.label || '')}">
      <div class="form-grid"><div class="field"><label for="qtD">Da quando</label><input class="input" type="datetime-local" id="qtD" value="${q ? new Date(q.start - new Date().getTimezoneOffset() * 6e4).toISOString().slice(0, 16) : ''}"></div><div class="field"><label for="qtC">Quanto spendevi al giorno (€)</label><input class="input" id="qtC" inputmode="decimal" value="${q ? String(q.cost || '').replace('.', ',') : ''}" placeholder="Es. 6"></div></div>
      <textarea class="input" id="qtW" rows="2" placeholder="Perché lo fai? Te lo ricordo quando arriva la voglia">${esc(q ? q.why || '' : '')}</textarea>${q ? `<button class="btn danger plain" id="qtX" style="align-self:flex-start">${ico('trash', 'sm')}Elimina</button>` : ''}`,
    onMount(el, api) { wireSeg(el, 'qtk', v => { kind = v; if (!$('#qtC', el).value && QK[v][2]) $('#qtC', el).placeholder = 'Es. ' + QK[v][2]; }); const x = $('#qtX', el); if (x) x.onclick = () => { S.quits = S.quits.filter(z => z !== q); save('quits'); api.close(); App.refresh(); }; } }); }
ACT.quitNew = () => quitEdit();
TODAY_CARDS.quits = 'Smetti di…'; if (!TODAY_DEFAULT.includes('quits')) TODAY_DEFAULT.push('quits');
TODAY_EXTRA.quits = () => S.quits.length ? `<section class="card span-6"><div class="card-h"><h3>💪 Ce la stai facendo</h3></div><div class="list flat" style="box-shadow:none;margin:0 -8px">${S.quits.map(q => `<button class="row" data-qto="${q.id}"><span style="font-size:22px">${QK[q.kind][1]}</span><span class="grow"><div class="t">${q.label || QK[q.kind][0]}: ${Math.floor(Quit.days(q))} giorni</div><div class="s">${q.cost ? eur(Quit.saved(q)) + ' risparmiati · ' : ''}${Quit.next(q) ? 'prossimo: ' + Quit.next(q)[1].toLowerCase() : '🏆'}</div></span><span class="btn sm" data-qtv="${q.id}">🆘</span></button>`).join('')}</div></section>` : '';
document.addEventListener('click', e => { const v = e.target.closest && e.target.closest('[data-qtv]'); if (v) { e.stopPropagation(); const q = S.quits.find(x => x.id === v.dataset.qtv); if (q) cravingHelp(q, () => App.refresh()); return; } const b = e.target.closest && e.target.closest('[data-qto]'); if (b) quitOpen(b.dataset.qto); }, true);
{ const old = Alerts.list.bind(Alerts); Alerts.list = function (hours = 48) { const out = old(hours), now = Date.now(); for (const q of S.quits) for (const [d, n] of QMIL) { const at = Quit.since(q) + d * 864e5, key = `qt:${q.id}:${d}:${Quit.since(q)}`; if (!this.fired[key] && at >= now - 10 * 60e3 && at <= now + hours * 36e5) out.push({ key, at: Math.max(at, this.at(dkey(new Date(at)), '09:00')), title: `🏆 ${n} senza ${(q.label || QK[q.kind][0]).toLowerCase()}!`, body: q.cost ? `Hai già risparmiato ${eur(d * q.cost)}` : 'Continua così', view: 'today' }); } return out; }; }

/* ---------- corsa: da zero a 5 km in 8 settimane ---------- */
const C25 = (() => { const R = (r, w, n) => Array.from({ length: n }, () => [['r', r], ['w', w]]).flat(); const W = [
  [R(60, 90, 8), R(60, 90, 8), R(60, 90, 8)], [R(90, 120, 6), R(90, 120, 6), R(90, 120, 6)], [[...R(90, 90, 2), ...R(180, 180, 2)], [...R(90, 90, 2), ...R(180, 180, 2)], [...R(90, 90, 2), ...R(180, 180, 2)]],
  [[['r', 180], ['w', 90], ['r', 300], ['w', 150], ['r', 180], ['w', 90], ['r', 300]], [['r', 180], ['w', 90], ['r', 300], ['w', 150], ['r', 180], ['w', 90], ['r', 300]], [['r', 180], ['w', 90], ['r', 300], ['w', 150], ['r', 180], ['w', 90], ['r', 300]]],
  [R(300, 180, 3), [['r', 480], ['w', 300], ['r', 480]], [['r', 1200]]], [[['r', 300], ['w', 180], ['r', 480], ['w', 180], ['r', 300]], [['r', 600], ['w', 180], ['r', 600]], [['r', 1500]]],
  [[['r', 1500]], [['r', 1500]], [['r', 1560]]], [[['r', 1680]], [['r', 1740]], [['r', 1800]]] ];
  return W.map(w => w.map(s => [['w', 300], ...s.filter((x, i, a) => !(i === a.length - 1 && x[0] === 'w')), ['w', 300]])); })();
const Run = { P() { return (S.health.c25k ||= { w: 0, d: 0, log: [] }); }, mins(s) { return Math.round(s.reduce((a, x) => a + x[1], 0) / 60); }, runMin(s) { return Math.round(s.filter(x => x[0] === 'r').reduce((a, x) => a + x[1], 0) / 60); } };
function runPlan() { const P = Run.P();
  const sh = openSheet({ title: '🏃 Da zero a 5 km', wide: true, left: { label: 'Chiudi' }, body: `<p class="muted" style="margin:0">8 settimane, 3 uscite a settimana, alternando corsa e camminata. Ti guido io con la voce: basta tenere il telefono in tasca. Se una seduta è troppo dura, ripetila: va benissimo.</p><div class="rn-weeks">${C25.map((w, wi) => `<div class="rn-w ${wi === P.w ? 'cur' : ''}"><b>Settimana ${wi + 1}</b>${w.map((s, di) => { const done = P.log.some(l => l.w === wi && l.d === di); return `<button class="rn-d ${done ? 'ok' : ''} ${wi === P.w && di === P.d ? 'next' : ''}" data-rn="${wi}.${di}"><span>${done ? '✓' : di + 1}</span><small>${Run.mins(s)}′ · corsa ${Run.runMin(s)}′</small></button>`; }).join('')}</div>`).join('')}</div>` });
  $$('[data-rn]', sh.el).forEach(b => b.onclick = () => { const [w, d] = b.dataset.rn.split('.').map(Number); sh.close(); runLive(w, d); }); setTimeout(() => $('.rn-w.cur', sh.el)?.scrollIntoView({ block: 'center' }), 200); return sh; }
function runLive(w, d) { const S0 = C25[w][d], total = S0.reduce((a, x) => a + x[1], 0); let i = 0, t0 = 0, acc = 0, paused = true, tm = 0, lock = null, started = false;
  const say = txt => { try { const u = new SpeechSynthesisUtterance(txt); u.lang = 'it-IT'; u.rate = 1.02; speechSynthesis.cancel(); speechSynthesis.speak(u); } catch (_) {} navigator.vibrate && navigator.vibrate(txt.startsWith('Corri') ? [300, 120, 300] : [500]); };
  const sh = openSheet({ title: `🏃 Settimana ${w + 1} · uscita ${d + 1}`, wide: true, left: { label: 'Chiudi', act: api => { if (started && !confirm2()) return; stop(); api.close(); } }, onClose: () => stop(),
    body: `<div class="rn-live"><span class="rn-ph" id="rnP">Pronti?</span><b class="tnum rn-t" id="rnT">${pad(Math.floor(S0[0][1] / 60))}:${pad(S0[0][1] % 60)}</b><span class="muted" id="rnN"></span><div class="qt-bar"><i id="rnB" style="width:0"></i></div><span class="muted tnum" id="rnR">${Math.round(total / 60)} min in totale</span></div><div class="rn-segs">${S0.map((x, j) => `<i class="${x[0]}" style="flex:${x[1]}" data-sg="${j}"></i>`).join('')}</div><div style="display:flex;gap:8px;justify-content:center"><button class="btn primary" id="rnGo" style="min-width:160px;height:48px">▶︎ Inizia</button><button class="btn" id="rnSk">Salta ›</button></div><p class="muted" style="margin:0;font-size:12.5px;text-align:center">Tieni lo schermo acceso per sentire la voce. Scaldati camminando: i primi 5 minuti sono già camminata.</p>` });
  const el = sh.el; let confirm2 = () => true;
  const elapsed = () => acc + (paused ? 0 : (Date.now() - t0) / 1000);
  const segAt = s => { let a = 0; for (let j = 0; j < S0.length; j++) { if (s < a + S0[j][1]) return [j, a + S0[j][1] - s]; a += S0[j][1]; } return [S0.length, 0]; };
  const label = j => j >= S0.length ? 'Fatto!' : S0[j][0] === 'r' ? 'Corri' : j === 0 ? 'Riscaldamento: cammina' : j === S0.length - 1 ? 'Defaticamento: cammina' : 'Cammina';
  const tick = () => { const s = elapsed(), [j, left] = segAt(s); if (j !== i) { i = j; if (j < S0.length) say(`${label(j)}${S0[j][0] === 'r' ? ` per ${S0[j][1] >= 120 ? Math.round(S0[j][1] / 60) + ' minuti' : S0[j][1] + ' secondi'}` : ''}`); else return finish(); }
    if (!$('#rnT', el)) return; $('#rnP', el).textContent = label(j); $('#rnP', el).className = 'rn-ph ' + (S0[j] ? S0[j][0] : ''); { const L2 = Math.ceil(left); $('#rnT', el).textContent = `${pad(Math.floor(L2 / 60))}:${pad(L2 % 60)}`; } $('#rnN', el).textContent = S0[j + 1] ? `Poi: ${label(j + 1).toLowerCase()} ${Math.round(S0[j + 1][1] / 60) || 1} min` : 'Ultimo tratto';
    $('#rnB', el).style.width = Math.min(100, s / total * 100) + '%'; $('#rnR', el).textContent = `${Math.ceil((total - s) / 60)} min rimasti`; $$('[data-sg]', el).forEach(z => z.classList.toggle('done', +z.dataset.sg < j)); if (left <= 3.2 && left > 2.2 && S0[j]) navigator.vibrate && navigator.vibrate(80); };
  const stop = () => { clearInterval(tm); try { lock && lock.release(); } catch (_) {} try { speechSynthesis.cancel(); } catch (_) {} };
  const finish = () => { stop(); const P = Run.P(); P.log.push({ w, d, at: todayK() }); if (w === P.w && d === P.d) { P.d++; if (P.d > 2) { P.d = 0; P.w = Math.min(7, P.w + 1); } } Health.dayW(todayK()).burn.push({ type: 'corsa', name: `Da zero a 5 km · S${w + 1} U${d + 1}`, min: Math.round(total / 60) }); save('health'); say('Fatto! Bravissimo, allenamento completato.'); confetti(100); Game.add(30, 'Corsa completata', { icon: 'flame' }); sh.close(); Island.toast({ icon: 'flame', c: 'var(--green)', t: 'Allenamento completato! 🏃', s: `${Math.round(total / 60)} minuti salvati in Salute`, ms: 3000 }); App.refresh(); };
  $('#rnGo', el).onclick = async () => { if (paused) { if (!started) { started = true; say(label(0)); confirm2 = () => window.confirm ? window.confirm('Interrompere l\'allenamento?') : true; } paused = false; t0 = Date.now(); tm = setInterval(tick, 250); try { lock = navigator.wakeLock ? await navigator.wakeLock.request('screen') : null; } catch (_) {} $('#rnGo', el).textContent = '❚❚ Pausa'; } else { acc = elapsed(); paused = true; clearInterval(tm); $('#rnGo', el).textContent = '▶︎ Riprendi'; } };
  $('#rnSk', el).onclick = () => { const s = elapsed(), [, left] = segAt(s); acc = s + left + .01; t0 = Date.now(); if (paused) tick(); };
  return sh; }
ACT.runPlan = () => runPlan();
{ const oA = VIEWS.health.actions; VIEWS.health.actions = () => `<button class="btn sm" data-act="runPlan" title="Da zero a 5 km">🏃<span class="hide-narrow">Corsa</span></button>` + oA(); }

/* ---------- leggimi ad alta voce ---------- */
const Say = { q: [], i: 0, rate: 1, on: false, title: '',
  voice() { try { const V = speechSynthesis.getVoices().filter(v => /^it/i.test(v.lang)); return V.find(v => /premium|enhanced|natural|alice|federica|elsa|google/i.test(v.name)) || V[0] || null; } catch (_) { return null; } },
  start(text, title) { if (!('speechSynthesis' in window)) { Island.toast({ icon: 'x', c: 'var(--orange)', t: 'Lettura ad alta voce non disponibile qui', ms: 2400 }); return; } const T = String(text || '').replace(/\s+/g, ' ').trim(); if (!T) return; this.q = T.match(/[^.!?;:]+[.!?;:]*\s*/g) || [T]; this.q = this.q.reduce((a, s) => { if (a.length && (a[a.length - 1] + s).length < 220) a[a.length - 1] += s; else a.push(s); return a; }, []); this.i = 0; this.title = title || 'Lettura'; this.on = true; this.bar(); this.play(); },
  play() { speechSynthesis.cancel(); if (this.i >= this.q.length) return this.end(); const u = new SpeechSynthesisUtterance(this.q[this.i]); u.lang = 'it-IT'; u.rate = this.rate; const v = this.voice(); if (v) u.voice = v; u.onend = () => { if (!this.on || this.paused) return; this.i++; this.play(); }; speechSynthesis.speak(u); this.paused = false; this.paint(); },
  toggle() { if (this.paused) { this.play(); } else { this.paused = true; speechSynthesis.cancel(); this.paint(); } },
  skip(n) { this.i = Math.max(0, Math.min(this.q.length - 1, this.i + n)); this.play(); },
  end() { this.on = false; try { speechSynthesis.cancel(); } catch (_) {} $('.say-bar')?.remove(); },
  bar() { $('.say-bar')?.remove(); const b = document.createElement('div'); b.className = 'say-bar'; b.innerHTML = `<span class="say-i">🔊</span><span class="grow" style="min-width:0"><b class="say-t"></b><small class="muted say-p"></small><div class="say-pr"><i></i></div></span><button class="icon-btn" data-sy="-1" aria-label="Indietro">⏮</button><button class="icon-btn say-pp" data-sy="p" aria-label="Pausa">❚❚</button><button class="icon-btn" data-sy="1" aria-label="Avanti">⏭</button><button class="say-rate" data-sy="r">1×</button><button class="icon-btn" data-sy="x" aria-label="Chiudi">×</button>`; document.body.appendChild(b);
    b.onclick = e => { const k = e.target.closest('[data-sy]'); if (!k) return; const v = k.dataset.sy; if (v === 'p') this.toggle(); else if (v === 'x') this.end(); else if (v === 'r') { this.rate = { 1: 1.25, 1.25: 1.5, 1.5: .85, .85: 1 }[this.rate] || 1; this.play(); } else this.skip(+v); }; },
  paint() { const b = $('.say-bar'); if (!b) return; $('.say-t', b).textContent = this.title; $('.say-p', b).textContent = `${this.i + 1} di ${this.q.length}`; $('.say-pr i', b).style.width = ((this.i + 1) / this.q.length * 100) + '%'; $('.say-pp', b).textContent = this.paused ? '▶︎' : '❚❚'; $('[data-sy=r]', b).textContent = String(this.rate).replace('.', ',') + '×'; },
};
try { speechSynthesis.getVoices(); speechSynthesis.onvoiceschanged = () => {}; } catch (_) {}
ACT.sayNote = () => { const n = S.notes[UI.note]; if (!n) return; const d = document.createElement('div'); d.innerHTML = n.html || ''; Say.start((n.title ? n.title + '. ' : '') + (d.textContent || n.text || ''), n.title || 'Nota'); };
ACT.sayDoc = () => { const L = S.docs.filter(d => /pdf|txt|md/i.test(d.ext || '')).sort((a, b) => (b.added || 0) - (a.added || 0));
  const sh = openSheet({ title: '🔊 Leggimi un documento', wide: true, left: { label: 'Chiudi' }, body: L.length ? `<div class="list" style="max-height:60vh;overflow:auto">${L.slice(0, 80).map(d => `<button class="row" data-syd="${d.id}"><span class="tile-ico" style="background:var(--red)">${ico('folder')}</span><span class="grow"><div class="t">${esc(d.name)}</div><div class="s">${esc(d.subject || '')}</div></span></button>`).join('')}</div>` : '<p class="muted">Nessun PDF nei Documenti.</p>' });
  $$('[data-syd]', sh.el).forEach(b => b.onclick = async () => { const d = S.docs.find(x => x.id === b.dataset.syd); b.disabled = true; try { const u = await Docs.url(d), blob = await (await fetch(u)).blob(), f = new File([blob], d.name, { type: blob.type || 'application/pdf' }); const text = /pdf/i.test(d.ext) ? (await readPdf(f, false)).text : await f.text(); sh.close(); Say.start(text, d.name.replace(/\.\w+$/, '')); } catch (_) { b.disabled = false; Island.toast({ icon: 'x', c: 'var(--red)', t: 'Non riesco ad aprire il file', ms: 2000 }); } }); };
{ const oA = VIEWS.notes.actions; VIEWS.notes.actions = () => (UI.note && S.notes[UI.note] ? `<button class="btn sm" data-act="sayNote" title="Leggimela ad alta voce">🔊<span class="hide-narrow">Ascolta</span></button>` : '') + oA(); }

/* ---------- calcolatrici ---------- */
const nfm = (n, d = 2) => (isFinite(n) ? n : 0).toLocaleString('it-IT', { minimumFractionDigits: d, maximumFractionDigits: d });
const CALC = {
  mutuo: ['🏠 Mutuo e prestiti', [['c', 'Importo (€)', 150000], ['r', 'Tasso annuo (TAN %)', 3.2], ['y', 'Durata (anni)', 25]], v => { const n = v.y * 12, i = v.r / 100 / 12, rata = i ? v.c * i / (1 - Math.pow(1 + i, -n)) : v.c / n; return [['Rata mensile', eur(rata), 1], ['Totale restituito', eur(rata * n)], ['Di cui interessi', eur(rata * n - v.c)]]; }],
  inter: ['📈 Interesse composto', [['c', 'Capitale iniziale (€)', 1000], ['m', 'Versamento mensile (€)', 100], ['r', 'Rendimento annuo (%)', 5], ['y', 'Anni', 10]], v => { let x = v.c; const i = v.r / 100 / 12; for (let k = 0; k < v.y * 12; k++) x = x * (1 + i) + v.m; const put = v.c + v.m * v.y * 12; return [['Avrai circa', eur(x), 1], ['Hai versato', eur(put)], ['Guadagno', eur(x - put)]]; }],
  sconto: ['🏷️ Sconti e IVA', [['p', 'Prezzo (€)', 100], ['s', 'Sconto (%)', 20], ['v', 'IVA (%)', 22]], v => { const f = v.p * (1 - v.s / 100); return [['Prezzo scontato', eur(f), 1], ['Risparmi', eur(v.p - f)], ['Senza IVA (scorporo)', eur(v.p / (1 + v.v / 100))], ['Con IVA aggiunta', eur(v.p * (1 + v.v / 100))]]; }],
  conto: ['🍽️ Dividi il conto', [['t', 'Totale (€)', 86.5], ['n', 'Persone', 4], ['m', 'Mancia (%)', 0]], v => { const tot = v.t * (1 + v.m / 100); return [['A testa', eur(tot / Math.max(1, v.n)), 1], ['Totale con mancia', eur(tot)]]; }],
  stip: ['⛽ Consumi auto', [['km', 'Km percorsi', 450], ['l', 'Litri', 30], ['p', 'Prezzo al litro (€)', 1.85]], v => [['Km con un litro', nfm(v.km / v.l, 1) + ' km/l', 1], ['Litri per 100 km', nfm(v.l / v.km * 100, 1) + ' l'], ['Costo al km', eur(v.l * v.p / v.km)], ['Costo del pieno', eur(v.l * v.p)]]],
  perc: ['➗ Percentuali', [['a', 'Valore', 40], ['b', 'Su un totale di', 160]], v => [['Percentuale', nfm(v.a / v.b * 100, 1) + '%', 1], [`Il ${nfm(v.a, 0)}% di ${nfm(v.b, 0)}`, nfm(v.a * v.b / 100)], ['Variazione da A a B', (v.b >= v.a ? '+' : '') + nfm((v.b - v.a) / v.a * 100, 1) + '%']]],
};
const UNITS2 = { Lunghezza: [['m', 1], ['km', 1000], ['cm', .01], ['mm', .001], ['miglia', 1609.344], ['piedi', .3048], ['pollici', .0254], ['iarde', .9144]], Peso: [['kg', 1], ['g', .001], ['libbre', .45359237], ['once', .0283495]], Volume: [['litri', 1], ['ml', .001], ['galloni (US)', 3.78541], ['tazze', .24], ['once liquide', .0295735]], Velocità: [['km/h', 1], ['m/s', 3.6], ['mph', 1.609344], ['nodi', 1.852]], Temperatura: [['°C', 'c'], ['°F', 'f'], ['K', 'k']], Superficie: [['m²', 1], ['ettari', 10000], ['km²', 1e6], ['piedi²', .092903]] };
ACT.calc = () => { let k = UI.calcK || 'mutuo';
  const sh = openSheet({ title: '🧮 Calcolatrici', wide: true, left: { label: 'Chiudi' }, body: `<div class="chips hs">${[...Object.entries(CALC).map(([x, c]) => [x, c[0]]), ['unit', '📏 Converti unità']].map(([x, n]) => `<button class="chip" data-clk="${x}" aria-pressed="${x === k}">${n}</button>`).join('')}</div><div id="clB"></div>` });
  const el = sh.el, paint = () => { const B = $('#clB', el);
    if (k === 'unit') { let cat = UI.calcU || 'Lunghezza'; const U = UNITS2[cat]; B.innerHTML = `<div class="chips" style="margin:8px 0">${Object.keys(UNITS2).map(c => `<button class="chip" data-clu="${c}" aria-pressed="${c === cat}">${c}</button>`).join('')}</div><div class="cl-u"><input class="input" id="cuV" inputmode="decimal" value="1"><select class="input" id="cuF">${U.map(u => `<option>${u[0]}</option>`).join('')}</select><span>=</span></div><div class="list" id="cuO"></div>`;
      const run = () => { const v = parseFloat($('#cuV', B).value.replace(',', '.')) || 0, f = U.find(u => u[0] === $('#cuF', B).value); let out; if (cat === 'Temperatura') { const c = f[1] === 'c' ? v : f[1] === 'f' ? (v - 32) * 5 / 9 : v - 273.15; out = [['°C', c], ['°F', c * 9 / 5 + 32], ['K', c + 273.15]]; } else { const base = v * f[1]; out = U.map(u => [u[0], base / u[1]]); } $('#cuO', B).innerHTML = out.filter(o => o[0] !== f[0]).map(o => `<div class="row"><span class="grow t tnum">${(Math.abs(o[1]) >= 1e5 || (Math.abs(o[1]) < .01 && o[1])) ? o[1].toExponential(3).replace('.', ',') : nfm(o[1], Math.abs(o[1]) < 10 ? 3 : 2)}</span><span class="muted">${o[0]}</span></div>`).join(''); };
      $$('[data-clu]', B).forEach(b => b.onclick = () => { UI.calcU = b.dataset.clu; paint(); }); $('#cuV', B).oninput = run; $('#cuF', B).onchange = run; run(); return; }
    const C = CALC[k], V = UI['calc_' + k] || Object.fromEntries(C[1].map(f => [f[0], f[2]]));
    B.innerHTML = `<div class="form-grid" style="margin-top:8px">${C[1].map(f => `<div class="field"><label for="cl_${f[0]}">${f[1]}</label><input class="input" id="cl_${f[0]}" inputmode="decimal" value="${String(V[f[0]]).replace('.', ',')}"></div>`).join('')}</div><div class="cl-out" id="clO"></div>`;
    const run = () => { const v = {}; for (const f of C[1]) v[f[0]] = parseFloat(($('#cl_' + f[0], B).value || '0').replace(/\./g, '').replace(',', '.')) || 0; UI['calc_' + k] = v; const R = C[2](v); $('#clO', B).innerHTML = R.map(r => `<div class="${r[2] ? 'big' : ''}"><span class="muted">${r[0]}</span><b class="tnum">${r[1]}</b></div>`).join(''); };
    C[1].forEach(f => $('#cl_' + f[0], B).oninput = run); run(); };
  $$('[data-clk]', el).forEach(b => b.onclick = () => { k = UI.calcK = b.dataset.clk; $$('[data-clk]', el).forEach(z => z.setAttribute('aria-pressed', z.dataset.clk === k)); paint(); }); paint(); return sh; };
{ const oA = VIEWS.money.actions; VIEWS.money.actions = function (...a) { const h = oA.apply(this, a); return h ? `<button class="btn sm" data-act="calc" title="Calcolatrici">🧮<span class="hide-narrow">Calcola</span></button>` + h : h; }; }

/* ---------- prezzi della spesa ---------- */
const Price = {
  norm(n) { return String(n || '').toLowerCase().replace(/[^a-zà-ù0-9 ]/g, ' ').replace(/\b(\d+([.,]\d+)?\s?(g|gr|kg|ml|cl|l|pz|x\d+))\b/g, ' ').replace(/\s+/g, ' ').trim(); },
  add(items, store, date) { const ch = []; for (const it of items || []) { const p = +String(it.price || '').replace(',', '.'); if (!it.name || !(p > 0) || p > 500) continue; const n = this.norm(it.name); if (n.length < 2 || /sconto|totale|resto|contanti|bancomat|iva|shopper|busta/.test(n)) continue; const prev = S.prices.filter(x => x.n === n).sort((a, b) => b.date.localeCompare(a.date))[0]; S.prices.push({ n, name: String(it.name).slice(0, 60), price: p, store: store || '', date: date || todayK() }); if (prev && Math.abs(p - prev.price) / prev.price >= .08) ch.push({ name: it.name, from: prev.price, to: p, store: prev.store }); }
    if (S.prices.length > 3000) S.prices.splice(0, S.prices.length - 3000); save('prices'); return ch; },
  products() { const M = new Map(); for (const x of S.prices) { const o = M.get(x.n) || { n: x.n, name: x.name, L: [] }; o.L.push(x); o.name = x.name; M.set(x.n, o); } return [...M.values()].map(o => { o.L.sort((a, b) => a.date.localeCompare(b.date)); const last = o.L[o.L.length - 1], byStore = {}; for (const x of o.L) { const s = x.store || '—'; if (!byStore[s] || x.date >= byStore[s].date) byStore[s] = x; } const best = Object.values(byStore).sort((a, b) => a.price - b.price)[0]; return { ...o, last, best, stores: Object.keys(byStore).length, trend: o.L.length > 1 ? (last.price - o.L[o.L.length - 2].price) / o.L[o.L.length - 2].price : 0 }; }); },
};
ACT.prices = () => { let q = '';
  const sh = openSheet({ title: '🏷️ Prezzi della spesa', wide: true, left: { label: 'Chiudi' }, right: { label: 'Aggiungi', primary: false, act: () => priceAdd(paint) }, body: '<input class="input" id="prQ" placeholder="Cerca un prodotto (es. latte, caffè)"><div id="prB"></div>' });
  const paint = () => { const P = Price.products().filter(p => !q || (p.name + ' ' + p.n).toLowerCase().includes(q)).sort((a, b) => b.last.date.localeCompare(a.last.date)), B = $('#prB', sh.el);
    B.innerHTML = S.prices.length ? `<p class="muted" style="margin:8px 0;font-size:13.5px">${Price.products().length} prodotti da ${new Set(S.prices.map(x => x.store)).size} negozi, imparati dagli scontrini che fotografi.</p><div class="list">${P.slice(0, 150).map(p => `<button class="row" data-prp="${esc(p.n)}"><span class="grow" style="min-width:0"><div class="t">${esc(cap(p.name.toLowerCase()))}</div><div class="s">${p.stores > 1 && p.best.store !== p.last.store ? `più economico da <b>${esc(p.best.store)}</b> (${eur(p.best.price)}) · ` : ''}${esc(p.last.store || '')} ${relDay(p.last.date, true).toLowerCase()}</div></span><b class="tnum">${eur(p.last.price)}</b>${p.trend ? `<span class="pill c" style="--c:${p.trend > 0 ? 'var(--red)' : 'var(--green)'}">${p.trend > 0 ? '▲' : '▼'} ${Math.round(Math.abs(p.trend) * 100)}%</span>` : ''}</button>`).join('')}</div>`
      : `<div class="empty"><span style="font-size:40px">🧾</span><b>Ancora nessun prezzo</b><p>Fotografa gli scontrini (Scontrini e garanzie): imparo il prezzo di ogni prodotto e ti dico dove costa meno e quando aumenta.</p><button class="btn primary" data-act="receiptScan">Fotografa uno scontrino</button></div>`;
    $$('[data-prp]', B).forEach(b => b.onclick = () => { const p = Price.products().find(x => x.n === b.dataset.prp); openSheet({ title: cap(p.name.toLowerCase()), wide: true, body: `<div class="dt-sum"><div><span class="muted">Ultimo</span><b class="tnum">${eur(p.last.price)}</b></div><div><span class="muted">Più basso</span><b class="tnum" style="color:var(--green)">${eur(Math.min(...p.L.map(x => x.price)))}</b></div><div><span class="muted">Più alto</span><b class="tnum" style="color:var(--red)">${eur(Math.max(...p.L.map(x => x.price)))}</b></div></div>${p.L.length > 1 && typeof lineChart === 'function' ? `<div>${(() => { const v = p.L.map(x => x.price), lo = Math.min(...v), hi = Math.max(...v), pad2 = Math.max(.1, (hi - lo) * .25); return lineChart(p.L.map(x => ({ v: x.price, label: dIt(x.date).slice(0, 5) })), { h: 150, min: Math.max(0, lo - pad2), max: hi + pad2, step: Math.max(.05, (hi - lo + 2 * pad2) / 4) }); })()}</div>` : ''}<div class="list">${p.L.slice().reverse().map(x => `<div class="row"><span class="grow"><div class="t">${esc(x.store || '—')}</div><div class="s">${dIt(x.date)}</div></span><b class="tnum">${eur(x.price)}</b></div>`).join('')}</div>` }); }); };
  $('#prQ', sh.el).oninput = e => { q = e.target.value.toLowerCase(); paint(); }; paint(); return sh; };
