/* ---------- parla con Orbita ---------- */
const Voice = {
  can() { return !!(window.SpeechRecognition || window.webkitSpeechRecognition) && !IN_CLAUDE && !window.orbitaDesktop; },
  say(t) { if (S.profile.voiceReply === false) return; try { const u = new SpeechSynthesisUtterance(t); u.lang = 'it-IT'; speechSynthesis.cancel(); speechSynthesis.speak(u); } catch (_) {} },
  monthSpent() { const m = todayK().slice(0, 7); return (S.money.tx || []).filter(t => t.date.startsWith(m) && t.amt < 0 && !t.loan && !(typeof Fin !== 'undefined' && Fin.isTr(t))).reduce((s, t) => s - t.amt, 0); },
  agenda(k) { const I = itemsOn(k).filter(i => i.kind !== 'ext' || true), T = S.tasks.filter(t => !t.done && t.due === k); const a = I.map(i => `${i.allDay || !i.s ? '' : i.s + ' '}${i.title}`), b = T.map(t => t.title); return !a.length && !b.length ? 'niente in programma' : [a.length && a.join(', '), b.length && `da fare: ${b.join(', ')}`].filter(Boolean).join('. '); },
  /** understands the sentence and does it; returns { ok, msg, speak } */
  async handle(raw) { const t = String(raw || '').trim().replace(/[.?!]+$/, ''), l = t.toLowerCase(); let m; if (!t) return { ok: false, msg: 'Non ho sentito niente' };
    if ((m = l.match(/^(?:dov'?è|dove (?:è|sono|ho messo|si trova(?:no)?)|dove l'ho messo)\s+(?:il |lo |la |i |gli |le |l'|mio |mia |miei |mie )?(.+)$/))) { const L = typeof Stash !== 'undefined' ? Stash.find(m[1]) : []; return L.length ? { ok: true, msg: `${L[0].what}: ${L[0].where}${L[0].room ? ' (' + L[0].room + ')' : ''}`, speak: /^(in|nel|nella|nello|nei|nelle|sul|sulla|sullo|sui|sotto|dietro|dentro|a |al |alla|allo|ai|da|dal|dalla|tra|fra|vicino|accanto)\b/i.test(L[0].where) ? `${L[0].what} è ${L[0].where}` : `${L[0].what}: ${L[0].where}` } : { ok: false, msg: `Non hai segnato dove hai messo “${m[1]}”`, speak: 'Non l\'hai segnato da nessuna parte' }; }
    if (/^(quanto ho speso|quanto ho spe|spese del mese|quanto spendo)/.test(l)) { const v = this.monthSpent(); return { ok: true, msg: `Questo mese hai speso ${eur(v)}`, speak: `Questo mese hai speso ${Math.round(v)} euro` }; }
    if ((m = l.match(/^(?:cosa|che cosa|che impegni|che programmi) (?:ho|devo fare|c'è)\s*(oggi|domani|dopodomani)?/))) { const d = m[1] === 'domani' ? 1 : m[1] === 'dopodomani' ? 2 : 0, s = this.agenda(addDK(todayK(), d)); return { ok: true, msg: `${cap(m[1] || 'oggi')}: ${s}`, speak: `${cap(m[1] || 'oggi')}: ${s}` }; }
    if (/^(ho parcheggiato|salva (?:il )?parcheggio|parcheggio qui|ricorda dove ho parcheggiato)/.test(l) && typeof geoHere === 'function') { let g = null; try { g = await geoHere(); } catch (_) {} S.park = { at: Date.now(), note: '', ...(g || {}) }; save('park'); App.refresh(); return { ok: true, msg: 'Parcheggio salvato' + (g ? '' : ' (senza posizione)'), speak: 'Ok, mi ricordo dove hai parcheggiato' }; }
    if ((m = l.match(/^(?:ho preso|preso)\s+(?:il |la |lo |l')?(.+)$/)) && typeof Med !== 'undefined') { const md = S.meds.find(x => x.name.toLowerCase().includes(m[1]) || m[1].includes(x.name.toLowerCase())); if (md) { const T = Med.times(md).filter(x => !Med.taken(md, todayK(), x)); const tt = T.sort((a, b) => Math.abs(hm2m(a) - hm2m(`${pad(new Date().getHours())}:${pad(new Date().getMinutes())}`)) - Math.abs(hm2m(b) - hm2m(`${pad(new Date().getHours())}:${pad(new Date().getMinutes())}`)))[0]; if (tt) { Med.take(md, tt); App.refresh(); return { ok: true, msg: `${md.name} delle ${tt}: preso`, speak: `Segnato, ${md.name} preso` }; } return { ok: true, msg: `${md.name}: oggi l'hai già preso`, speak: 'L\'hai già segnato oggi' }; } }
    if ((m = l.match(/^(?:apri|vai a|vai su|vai in|mostrami|mostra)\s+(?:la |il |lo |le |i |gli |l')?(.+)$/))) { const q = m[1]; const hit = Object.entries(TITLES).find(([k, n]) => String(n).toLowerCase() === q) || Object.entries(TITLES).find(([k, n]) => String(n).toLowerCase().includes(q) || q.includes(String(n).toLowerCase())); if (hit) { go(hit[0]); return { ok: true, msg: `Apro ${hit[1]}` }; } const act = (typeof CMD_ACT !== 'undefined' ? CMD_ACT : []).find(c => c[0].toLowerCase().includes(q)); if (act) { act[2](); return { ok: true, msg: act[0] }; } }
    if ((m = l.match(/^(?:ho messo|metto)\s+(?:il |la |lo |i |gli |le |l')?(.+?)\s+(nel|nella|nello|nei|nelle|sul|sulla|sullo|sui|sotto|dietro|dentro|in|a|al|alla)\s+(.+)$/)) && typeof Stash !== 'undefined') { const what = cap(m[1]), where = `${m[2]} ${m[3]}`; const ex = S.stash.find(x => x.what.toLowerCase() === what.toLowerCase()); if (ex) Object.assign(ex, { where, at: Date.now() }); else S.stash.push({ id: uid(), what, where, at: Date.now(), created: Date.now() }); save('stash'); return { ok: true, msg: `${what} → ${where}`, speak: 'Ok, me lo ricordo' }; }
    if (/\?$/.test(raw) || /^(come|perché|quando|quale|quali|chi|consigliami|spiegami|dimmi|cerca)\b/.test(l)) { go('assistant'); setTimeout(() => Assistant.send(t), 250); return { ok: true, msg: 'Chiedo al Segretario' }; }
    let r = null; try { r = await QuickX.commit(t); } catch (_) {}
    if (r && r.ok) return { ok: true, msg: r.msg, speak: 'Fatto' };
    go('assistant'); setTimeout(() => Assistant.send(t), 250); return { ok: true, msg: 'Chiedo al Segretario' }; },
};
function voiceSheet() { let rec = null, txt = '', fin = '', done = false;
  const sh = openSheet({ title: '🎙️ Parla con Orbita', left: { label: 'Chiudi' }, onClose: () => { done = true; try { rec && rec.abort(); } catch (_) {} },
    body: `<div class="vc-live"><div class="vc-orb" id="vcO"><i></i><i></i><i></i></div><p class="vc-tx" id="vcT">${Voice.can() ? 'Ti ascolto…' : 'Scrivi qui sotto'}</p></div><div style="display:flex;gap:8px"><input class="input" id="vcI" placeholder="Oppure scrivi (es. ho speso 12 euro di benzina)" style="flex:1"><button class="btn primary" id="vcGo">Vai</button></div>
      <div class="chips hs" id="vcEx">${['Cosa ho domani?', 'Dov\'è il passaporto?', 'Ho speso 12 euro di pizza', 'Ricordami domani alle 9 il dentista', 'Comprare latte e uova', 'Quanto ho speso questo mese?', 'Ho parcheggiato', 'Apri la dieta'].map(x => `<button class="chip" data-vex="${esc(x)}">${esc(x)}</button>`).join('')}</div>` });
  const el = sh.el, T = $('#vcT', el), O = $('#vcO', el);
  const run = async text => { if (!text.trim()) return; done = true; try { rec && rec.stop(); } catch (_) {} O.classList.remove('on'); O.classList.add('busy'); T.textContent = `“${text}”`; const r = await Voice.handle(text); O.classList.remove('busy'); if (sh.closed) { Island.toast({ icon: 'mic', c: r.ok ? 'var(--purple)' : 'var(--orange)', t: r.msg, ms: 3200 }); return; } T.innerHTML = `<span class="muted">“${esc(text)}”</span><br><b>${esc(r.msg)}</b>`; if (r.speak) Voice.say(r.speak); if (r.ok && UI.view !== 'assistant') setTimeout(() => { if (!sh.closed) sh.close(); }, 2600); else if (UI.view === 'assistant') sh.close(); };
  $('#vcGo', el).onclick = () => run($('#vcI', el).value); $('#vcI', el).onkeydown = e => { if (e.key === 'Enter') run(e.target.value); }; $$('[data-vex]', el).forEach(b => b.onclick = () => run(b.dataset.vex));
  if (Voice.can()) { try { const SR = window.SpeechRecognition || window.webkitSpeechRecognition; rec = new SR(); rec.lang = 'it-IT'; rec.interimResults = true; rec.continuous = false; O.classList.add('on');
      rec.onresult = e => { let it = ''; for (let i = e.resultIndex; i < e.results.length; i++) { if (e.results[i].isFinal) fin += e.results[i][0].transcript; else it += e.results[i][0].transcript; } txt = (fin + it).trim(); T.textContent = txt || 'Ti ascolto…'; };
      rec.onerror = e => { O.classList.remove('on'); if (e.error === 'not-allowed') T.textContent = 'Consenti il microfono, oppure scrivi qui sotto'; else if (e.error === 'no-speech') T.textContent = 'Non ho sentito niente: tocca il cerchio e riprova'; };
      rec.onend = () => { O.classList.remove('on'); if (!done && (fin || txt).trim()) run((fin || txt).trim()); };
      O.onclick = () => { if (O.classList.contains('on')) { try { rec.stop(); } catch (_) {} return; } fin = txt = ''; done = false; try { rec.start(); O.classList.add('on'); T.textContent = 'Ti ascolto…'; } catch (_) {} };
      rec.start(); } catch (_) { O.classList.remove('on'); T.textContent = 'Microfono non disponibile: scrivi qui sotto'; } }
  else setTimeout(() => $('#vcI', el).focus(), 80);
  return sh; }
ACT.voice = () => voiceSheet();
/* floating microphone */
{ const fab = document.createElement('button'); fab.className = 'vc-fab'; fab.setAttribute('aria-label', 'Parla con Orbita'); fab.innerHTML = `<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 11a7 7 0 0 0 14 0M12 18v3"/></svg>`; fab.onclick = () => voiceSheet(); document.body.appendChild(fab);
  const sync = () => { fab.hidden = S.profile.voiceFab === false || !!document.querySelector('.lk-wrap'); }; sync(); try { const L = $('#layer'); if (L) new MutationObserver(() => fab.classList.toggle('vc-off', !!L.querySelector('.sheet-wrap'))).observe(L, { childList: true }); } catch (_) {} const oR = App.refreshChrome.bind(App); App.refreshChrome = function () { const r = oR(); sync(); return r; }; }
document.addEventListener('keydown', e => { if ((e.metaKey || e.ctrlKey) && e.shiftKey && e.key.toLowerCase() === 'o') { e.preventDefault(); voiceSheet(); } });

/* ---------- una foto al giorno ---------- */
if (!CORE.includes('daypics')) CORE.push('daypics');
if (!S.daypics || Array.isArray(S.daypics)) S.daypics = {};
const DayPic = {
  get(k) { return S.daypics[k] || null; },
  async set(k, file, caption) { const t = await photoThumb(file, 200, .6), old = UI.docFilter; let doc = null; UI.docFilter = 'all'; try { const before = new Set(S.docs.map(d => d.id)); await Docs.upload([new File([file], `Foto del ${k}.${(file.name.split('.').pop() || 'jpg').toLowerCase()}`, { type: file.type || 'image/jpeg' })]); const d = S.docs.find(x => !before.has(x.id)); if (d) { d.subject = 'Una foto al giorno'; doc = d.id; save('docs'); } } catch (_) {} UI.docFilter = old;
    S.daypics[k] = { t, d: doc, c: caption || (S.daypics[k] || {}).c || '', at: Date.now() }; const keys = Object.keys(S.daypics).sort(); if (keys.length > 400) for (const x of keys.slice(0, keys.length - 400)) delete S.daypics[x]; save('daypics'); Game.add(5, 'Foto del giorno', { silent: true }); },
  async big(k) { const p = this.get(k); if (!p) return null; if (p.d) { const d = S.docs.find(x => x.id === p.d); if (d) { try { const u = await Docs.url(d); if (u) return u; } catch (_) {} } } return p.t; },
  month(ym) { return Object.keys(S.daypics).filter(k => k.startsWith(ym)).sort(); },
  streak() { let n = 0, k = todayK(); if (!this.get(k)) k = addDK(k, -1); while (this.get(k)) { n++; k = addDK(k, -1); } return n; },
};
function dayPicAdd(k = todayK(), after) { const i = document.createElement('input'); i.type = 'file'; i.accept = 'image/*'; i.onchange = async () => { const f = i.files[0]; if (!f) return; await DayPic.set(k, f); App.refresh(); Island.toast({ icon: 'image', c: 'var(--pink)', t: 'Foto del giorno salvata 📸', s: DayPic.streak() > 1 ? `${DayPic.streak()} giorni di fila` : 'Domani un\'altra!', action: { label: 'Didascalia', fn: () => dayPicView(k) }, ms: 3200 }); after && after(); }; i.click(); }
async function dayPicView(k) { const p = DayPic.get(k); if (!p) return dayPicAdd(k); const u = await DayPic.big(k);
  openSheet({ title: cap(parseD(k).toLocaleDateString('it-IT', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })), wide: true, left: { label: 'Chiudi' }, right: { label: 'Fine', act: s => { p.c = $('#dpC', s.el).value.trim(); save('daypics'); s.close(); App.refresh(); } },
    body: `<img src="${u}" alt="" class="dp-big"><input class="input" id="dpC" placeholder="Una riga su questo giorno" value="${esc(p.c || '')}"><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" id="dpR">${ico('image', 'sm')}Cambia foto</button><button class="btn danger plain" id="dpX">${ico('trash', 'sm')}Togli</button></div>`,
    onMount(el, api) { $('#dpR', el).onclick = () => { api.close(); dayPicAdd(k); }; $('#dpX', el).onclick = () => { const prev = S.daypics[k]; delete S.daypics[k]; save('daypics'); api.close(); App.refresh(); undoToast('Foto tolta', () => { S.daypics[k] = prev; save('daypics'); App.refresh(); }); }; } }); }
function dayPicAlbum(ym = todayK().slice(0, 7)) {
  const sh = openSheet({ title: '📸 Una foto al giorno', wide: true, left: { label: 'Chiudi' }, body: '<div id="daB" style="display:flex;flex-direction:column;gap:12px"></div>' });
  const paint = () => { const B = $('#daB', sh.el), [y, mo] = ym.split('-').map(Number), first = new Date(y, mo - 1, 1), n = new Date(y, mo, 0).getDate(), off = (first.getDay() + 6) % 7, L = DayPic.month(ym);
    B.innerHTML = `<div style="display:flex;align-items:center;gap:8px"><button class="icon-btn" id="daP">${ico('left', 'sm')}</button><b class="grow" style="text-align:center;font-size:18px">${cap(MONTHS[mo - 1])} ${y}</b><button class="icon-btn" id="daN" ${ym >= todayK().slice(0, 7) ? 'disabled' : ''}>${ico('right', 'sm')}</button></div>
      <div class="dp-cal">${['L', 'M', 'M', 'G', 'V', 'S', 'D'].map(d => `<span class="dp-h">${d}</span>`).join('')}${'<span></span>'.repeat(off)}${Array.from({ length: n }, (_, i) => { const k = `${ym}-${pad(i + 1)}`, p = DayPic.get(k), fut = k > todayK(); return `<button class="dp-d ${p ? 'has' : ''} ${k === todayK() ? 'today' : ''}" data-dpk="${k}" ${fut ? 'disabled' : ''} ${p ? `style="background-image:url('${p.t}')"` : ''}><span>${i + 1}</span></button>`; }).join('')}</div>
      <p class="muted" style="margin:0;font-size:13.5px">${L.length} foto questo mese${DayPic.streak() > 1 ? ` · ${DayPic.streak()} giorni di fila 🔥` : ''}. Tocca un giorno per aggiungere o vedere la foto.</p>
      <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" id="daV" ${L.length < 2 ? 'disabled' : ''}>▶︎ Il video del mese</button><button class="btn" id="daC" ${L.length < 2 ? 'disabled' : ''}>${ico('share', 'sm')}Collage</button></div>`;
    $('#daP', B).onclick = () => { const d = new Date(y, mo - 2, 1); ym = `${d.getFullYear()}-${pad(d.getMonth() + 1)}`; paint(); }; $('#daN', B).onclick = () => { const d = new Date(y, mo, 1); ym = `${d.getFullYear()}-${pad(d.getMonth() + 1)}`; paint(); };
    $$('[data-dpk]', B).forEach(b => b.onclick = () => DayPic.get(b.dataset.dpk) ? dayPicView(b.dataset.dpk) : dayPicAdd(b.dataset.dpk, paint));
    $('#daV', B).onclick = () => dayPicMovie(ym); $('#daC', B).onclick = () => dayPicCollage(ym); };
  paint(); return sh; }
async function dpImgs(ym) { const L = DayPic.month(ym), out = []; for (const k of L) { const u = await DayPic.big(k); const img = await new Promise(ok => { const i = new Image(); i.crossOrigin = 'anonymous'; i.onload = () => ok(i); i.onerror = () => ok(null); i.src = u; }); if (img) out.push({ k, img, c: DayPic.get(k).c }); } return out; }
