  const read = files => { if (files.length) smartScan({ files, trip: x.id, noDoc: true, onDone: () => paint() }); };
  const u = $('#trU', B); if (u) u.onclick = () => { const i = document.createElement('input'); i.type = 'file'; i.multiple = true; i.accept = 'image/*,.pdf'; i.onchange = async () => { const F = [...i.files], before = new Set(S.docs.map(d => d.id)), old = UI.docFilter; UI.docFilter = 'all'; try { await Docs.upload(F); } catch (_) {} UI.docFilter = old; attach(before); paint(); read(F); }; i.click(); };
