    <div class="list flat"><div class="row"><span class="grow t">★ Preferito</span>${toggleBtn('nbFav', b.fav)}</div><div class="row"><span class="grow"><div class="t">🔒 Sola lettura</div><div class="s">Sfogli e presenti senza modificare per sbaglio</div></span>${toggleBtn('nbRO', b.ro)}</div><div class="row"><span class="grow"><div class="t">Disegna solo con Apple Pencil</div><div class="s">Le dita spostano e ingrandiscono</div></span>${toggleBtn('bPen', S.profile.pencilOnly)}</div></div>
