/* =========================================================
   ASSISTANT — "Segretario": Claude with page tools
   ========================================================= */
const CAT_KEYS = Object.keys(CATS);
const Assistant = {
  turns: [], busy: false, ctl: null,
  load() { try { this.turns = JSON.parse(localStorage.getItem('pitwall.chat') || '[]'); } catch (_) { this.turns = []; } },
  persist() { try { localStorage.setItem('pitwall.chat', JSON.stringify(this.turns.slice(-40))); } catch (_) {} },
  context() {
    const t = todayK(), d = new Date();
    const agenda = [];
    for (let i = 0; i < 14; i++) { const k = addDK(t, i); const its = itemsOn(k); if (its.length) agenda.push(`${k} (${DOW[parseD(k).getDay()]}): ` + its.map(x => `${x.allDay ? 'tutto il giorno' : x.s + '-' + x.e} ${x.title} [${catOf(x.cat).n}${x.kind === 'event' ? ', id ' + x.id : ''}]`).join('; ')); }
    const tasks = openTasks().sort(taskSort).slice(0, 25).map(x => `- ${x.title}${x.due ? ' (scadenza ' + x.due + ')' : ''}${x.prio ? ' priorità ' + x.prio : ''} [id ${x.id}]`);
    const st = Exams.stats();
    const ex = S.exams.filter(e => e.status === 'planned').map(e => `- ${e.name}, ${e.cfu} CFU${e.date ? ', il ' + e.date : ', data da fissare'}`);
    const goals = S.goals.filter(g => !g.done).map(g => `- ${g.title}: ${g.steps.filter(s => s.done).length}/${g.steps.length} tappe${g.deadline ? ', scadenza ' + g.deadline : ''}`);
    return `Sei il segretario personale di ${S.profile.name || 'questa persona'} dentro Orbita, la sua app di planning per studio e lavoro${S.profile.course ? ' (corso: ' + S.profile.course + ')' : ''}. Rispondi sempre in italiano, in modo diretto e pratico, frasi brevi, niente markdown pesante (al massimo elenchi con "• "). Quando chiede di aggiungere, spostare o pianificare qualcosa, usa gli strumenti invece di limitarti a descriverlo, poi conferma in una riga cosa hai fatto. Se manca un dettaglio davvero necessario chiedilo; altrimenti scegli un valore sensato e dillo. Per pianificare lo studio usa find_free_time ed evita sovrapposizioni con gli impegni esistenti. Non inventare impegni che non vedi qui sotto.

Adesso: ${DOW[d.getDay()]} ${t}, ore ${nowHM()} (fuso Europa/Roma).
Categorie disponibili: ${CAT_KEYS.join(', ')}.

AGENDA DEI PROSSIMI 14 GIORNI:
${agenda.join('\n') || 'nessun impegno'}

PROMEMORIA APERTI:
${tasks.join('\n') || 'nessuno'}

PROGETTI:
${(S.projects || []).filter(p => p.status !== 'done').map(p => `- ${p.name}: ${Math.round(Projects.prog(p) * 100)}%, ${Projects.tasks(p).filter(x => !x.done).length} attività aperte${p.due ? ', scadenza ' + p.due : ''}`).join('\n') || 'nessuno'}

CORSI:
${S.courses.map(c => `- ${c.name}: ${Math.round(Courses.prog(c) * 100)}% del programma; da studiare: ${(c.topics || []).filter(t => !t.st).slice(0, 8).map(t => t.t).join(', ') || 'niente'}`).join('\n') || 'nessuno'}

ABITUDINI OGGI: ${S.habits.map(h => `${h.name} ${Habits.done(h) ? 'fatta' : 'da fare'} (serie ${Habits.streak(h)})`).join('; ') || 'nessuna'}
TRASFERTE: ${S.trips.filter(x => (x.to || x.from) >= t).map(x => `${x.title} a ${x.place || '?'} dal ${x.from}`).join('; ') || 'nessuna'}
SPESE DEL MESE: ${eur(-Money.month(t.slice(0, 7)).filter(x => x.amt < 0 && !x.loan && x.type !== "transfer").reduce((s, x) => s + x.amt, 0))}
CONTI: ${(() => { try { Fin.ensure(); return S.money.wallets.filter(w => !w.hidden).map(w => `${w.name} ${eur(Fin.balance(w))}`).join('; '); } catch (_) { return ''; } })()} · ABBONAMENTI: ${eur(Money.subsMonthly())}/mese

ESAMI: media ponderata ${st.n ? fmt1(st.w) : 'n.d.'}, ${st.cfu}/${S.profile.totalCfu} CFU, obiettivo media ${S.profile.targetMedia}.
Da sostenere:
${ex.join('\n') || 'nessuno'}

OBIETTIVI:
${goals.join('\n') || 'nessuno'}

GAMIFICATION: livello ${Game.info().n} (${Game.info().title}), serie di ${Game.currentStreak()} giorni.`;
  },
  tools() {
    const self = this;
    const okDate = v => /^\d{4}-\d{2}-\d{2}$/.test(String(v || '')) ? String(v) : null;
    const okTime = v => /^\d{1,2}:\d{2}$/.test(String(v || '')) ? String(v).padStart(5, '0') : null;
    return [
      { name: 'add_event', description: 'Aggiunge un evento al calendario. Restituisce l\'evento creato con il suo id.', inputSchema: { type: 'object', properties: { title: { type: 'string' }, date: { type: 'string', description: 'YYYY-MM-DD' }, start: { type: 'string', description: 'HH:MM, ometti per tutto il giorno' }, end: { type: 'string', description: 'HH:MM' }, category: { type: 'string', enum: CAT_KEYS }, location: { type: 'string' }, recurrence: { type: 'string', enum: Object.keys(REC) }, until: { type: 'string', description: 'YYYY-MM-DD fine ripetizione' } }, required: ['title', 'date'] },
        execute(i) { const date = okDate(i.date); if (!date) throw new Error('data non valida, usa YYYY-MM-DD'); const s = okTime(i.start), e = okTime(i.end) || (s ? m2hm(hm2m(s) + 60) : ''); const ev = { id: uid(), title: String(i.title || 'Evento'), date, start: s || '', end: s ? e : '', allDay: !s, cat: CAT_KEYS.includes(i.category) ? i.category : 'studio', rec: REC[i.recurrence] ? i.recurrence : 'none', until: okDate(i.until), loc: String(i.location || ''), created: Date.now() }; S.events.push(ev); save('events'); Game.bump('events'); self.note('cal', `Evento: ${ev.title} · ${relDay(date, true)}${s ? ' ' + s : ''}`); return { ok: true, id: ev.id }; } },
      { name: 'move_event', description: 'Sposta o rinomina un evento esistente (per id). Restituisce ok.', inputSchema: { type: 'object', properties: { id: { type: 'string' }, date: { type: 'string' }, start: { type: 'string' }, end: { type: 'string' }, title: { type: 'string' } }, required: ['id'] },
        execute(i) { const ev = S.events.find(x => x.id === String(i.id)); if (!ev) throw new Error('evento non trovato'); const dur = hm2m(ev.end) - hm2m(ev.start) || 60; if (okDate(i.date)) ev.date = i.date; if (okTime(i.start)) { ev.start = okTime(i.start); ev.end = okTime(i.end) || m2hm(hm2m(ev.start) + dur); ev.allDay = false; } if (i.title) ev.title = String(i.title); save('events'); self.note('cal', `Spostato: ${ev.title} · ${relDay(ev.date, true)} ${ev.start}`); return { ok: true }; } },
      { name: 'add_task', description: 'Aggiunge un promemoria (cosa da fare). Restituisce l\'id.', inputSchema: { type: 'object', properties: { title: { type: 'string' }, due: { type: 'string', description: 'YYYY-MM-DD, facoltativa' }, priority: { type: 'integer', minimum: 0, maximum: 3 }, category: { type: 'string', enum: CAT_KEYS }, project: { type: 'string', description: 'nome di un progetto esistente, facoltativo' }, course: { type: 'string', description: 'nome di un corso esistente, facoltativo' } }, required: ['title'] },
        execute(i) { const pj = i.project ? (S.projects || []).find(p => p.name.toLowerCase().includes(String(i.project).toLowerCase())) : null, cr = i.course ? S.courses.find(c => c.name.toLowerCase().includes(String(i.course).toLowerCase())) : null; const t = { id: uid(), title: String(i.title), due: okDate(i.due), prio: clamp(+i.priority || 0, 0, 3), cat: CAT_KEYS.includes(i.category) ? i.category : pj ? 'lavoro' : cr ? 'uni' : null, project: pj ? pj.id : null, course: cr ? cr.id : null, done: false, created: Date.now() }; S.tasks.push(t); save('tasks'); self.note('list', `Promemoria: ${t.title}${t.due ? ' · ' + relDay(t.due, true) : ''}`); return { ok: true, id: t.id }; } },
      { name: 'complete_task', description: 'Segna come completato un promemoria esistente (per id).', inputSchema: { type: 'object', properties: { id: { type: 'string' } }, required: ['id'] },
        execute(i) { const t = S.tasks.find(x => x.id === String(i.id)); if (!t) throw new Error('promemoria non trovato'); if (!t.done) { t.done = true; t.doneAt = Date.now(); save('tasks'); Game.bump('tasks'); Game.add(PRIO_XP[t.prio || 0], 'Promemoria completato', { silent: true }); } self.note('check', `Completato: ${t.title}`); return { ok: true }; } },
      { name: 'add_exam', description: 'Aggiunge un esame al libretto: da sostenere (planned) o superato (passed, con voto 18-30).', inputSchema: { type: 'object', properties: { name: { type: 'string' }, cfu: { type: 'integer' }, status: { type: 'string', enum: ['planned', 'passed'] }, date: { type: 'string' }, time: { type: 'string' }, grade: { type: 'integer', minimum: 18, maximum: 30 }, lode: { type: 'boolean' } }, required: ['name', 'cfu'] },
        execute(i) { const passed = i.status === 'passed'; const x = { id: uid(), name: String(i.name), cfu: clamp(+i.cfu || 6, 1, 30), status: passed ? 'passed' : 'planned', grade: passed ? clamp(+i.grade || 18, 18, 30) : null, lode: passed && !!i.lode && +i.grade === 30, date: okDate(i.date), time: okTime(i.time) }; S.exams.push(x); save('exams'); self.note('grad', `Esame: ${x.name} (${x.cfu} CFU)${passed ? ' · ' + (x.lode ? '30L' : x.grade) : x.date ? ' · ' + relDay(x.date, true) : ''}`); if (passed) Game.add(x.cfu * 10, 'Esame superato', { silent: true }); return { ok: true, id: x.id, media: fmt1(Exams.stats().w) }; } },
      { name: 'find_free_time', description: 'Trova le fasce libere in un giorno, tra impegni esistenti. Restituisce un elenco di intervalli HH:MM-HH:MM lunghi almeno "minutes".', inputSchema: { type: 'object', properties: { date: { type: 'string' }, minutes: { type: 'integer' }, from: { type: 'string', description: 'HH:MM, default 08:30' }, to: { type: 'string', description: 'HH:MM, default 22:00' } }, required: ['date'] },
        execute(i) { const k = okDate(i.date); if (!k) throw new Error('data non valida'); const a = hm2m(okTime(i.from) || '08:30'), b = hm2m(okTime(i.to) || '22:00'), need = +i.minutes || 60; const busy = itemsOn(k).filter(x => !x.allDay && x.s).map(x => [hm2m(x.s), hm2m(x.e) || hm2m(x.s) + 60]).sort((p, q) => p[0] - q[0]); const free = []; let cur = a; if (k === todayK()) cur = Math.max(cur, Math.ceil((new Date().getHours() * 60 + new Date().getMinutes()) / 15) * 15); for (const [s, e] of busy) { if (s - cur >= need) free.push(`${m2hm(cur)}-${m2hm(s)}`); cur = Math.max(cur, e); } if (b - cur >= need) free.push(`${m2hm(cur)}-${m2hm(b)}`); return { date: k, free }; } },
      { name: 'create_note', description: 'Crea una nota. Nel contenuto usa righe che iniziano con "# " per i titoli, "- [ ] " per le liste di controllo e "- " per gli elenchi.', inputSchema: { type: 'object', properties: { title: { type: 'string' }, content: { type: 'string' } }, required: ['title', 'content'] },
        execute(i) { const html = mdLite(String(i.content || '')); const n = { id: uid(), title: String(i.title), html, text: htmlToText(html), updated: Date.now(), created: Date.now() }; S.notes[n.id] = n; save('note-' + n.id); self.note('note', `Nota: ${n.title}`); return { ok: true, id: n.id }; } },
      { name: 'add_goal', description: 'Crea un obiettivo gamificato con tappe e ricompensa in XP.', inputSchema: { type: 'object', properties: { title: { type: 'string' }, steps: { type: 'array', items: { type: 'string' } }, xp: { type: 'integer', enum: [50, 100, 250, 500] }, deadline: { type: 'string' } }, required: ['title', 'steps'] },
        execute(i) { const g = { id: uid(), title: String(i.title), desc: '', xp: [50, 100, 250, 500].includes(+i.xp) ? +i.xp : 100, deadline: okDate(i.deadline), steps: (Array.isArray(i.steps) ? i.steps : []).slice(0, 20).map(t => ({ id: uid(), t: String(t), done: false })), c: 'purple', done: false, created: Date.now() }; S.goals.push(g); save('goals'); self.note('target', `Obiettivo: ${g.title} · ${g.steps.length} tappe`); return { ok: true }; } },
      { name: 'add_transaction', description: 'Registra una spesa (importo negativo) o un\'entrata (positivo) in euro nelle Finanze.', inputSchema: { type: 'object', properties: { amount: { type: 'number', description: 'negativo per le spese' }, category: { type: 'string', enum: [...Object.keys(MCAT), ...Object.keys(ICAT)] }, note: { type: 'string' }, date: { type: 'string' }, wallet: { type: 'string', description: 'conto, carta o contanti usati (nome); se manca uso il predefinito' } }, required: ['amount', 'note'] },
        execute(i) { const amt = +i.amount; if (!amt) throw new Error('importo mancante'); Fin.ensure(); const cat = (amt > 0 ? ICAT : MCAT)[i.category] ? i.category : (amt > 0 ? 'altro_in' : 'altro'); const w = Fin.findWallet(i.wallet); S.money.tx.push({ id: uid(), date: okDate(i.date) || todayK(), amt, cat, note: String(i.note || ''), wallet: w ? w.id : null, created: Date.now() }); save('money'); self.note('wallet', `${amt > 0 ? 'Entrata' : 'Spesa'}: ${i.note} · ${eur(Math.abs(amt))}`); return { ok: true }; } },
      { name: 'mark_habit', description: 'Segna come fatta oggi un\'abitudine esistente, cercandola per nome.', inputSchema: { type: 'object', properties: { name: { type: 'string' } }, required: ['name'] },
        execute(i) { const h = S.habits.find(x => x.name.toLowerCase().includes(String(i.name || '').toLowerCase())); if (!h) throw new Error('abitudine non trovata'); if (!Habits.done(h)) Habits.toggle(h.id); self.note('flame', `Abitudine: ${h.name}`); return { ok: true, streak: Habits.streak(h) }; } },
    ].concat(Spot.usable() ? [
      { name: 'spotify_search', description: 'Cerca su Spotify (brani, artisti, album, playlist, mood) con il collegamento Spotify dell\'utente. Restituisce fino a 6 risultati con nome, autore e link.', inputSchema: { type: 'object', properties: { query: { type: 'string', description: 'Ricerca in italiano, così come la direbbe l\'utente' } }, required: ['query'] },
        async execute(i) { await Spot.search(String(i.query || '')); const r = (Spot.results || []).slice(0, 6).map(x => ({ name: x.name, by: x.who, type: x.type, url: x.url })); self.note('music', `Spotify: cercato “${i.query}”`); if (!r.length) throw new Error(Spot.lastErr || 'nessun risultato'); return r; } },
      { name: 'spotify_create_playlist', description: 'Crea una playlist privata nell\'account Spotify dell\'utente (serve Premium) e la imposta come musica per il focus. Usala solo se l\'utente chiede esplicitamente di creare una playlist.', inputSchema: { type: 'object', properties: { request: { type: 'string', description: 'Richiesta in italiano che inizia con "Crea una playlist…", con durata in minuti se nota' } }, required: ['request'] },
        async execute(i) { const p = await Spot.generate(String(i.request || '')); if (!p && Spot.lastErr) throw new Error(Spot.lastErr); self.note('music', p ? `Playlist Spotify: ${p.name}` : 'Richiesta inviata a Spotify'); return p ? { ok: true, name: p.name, url: p.url } : { ok: true, note: 'creata, si trova nella libreria Spotify' }; } },
    ] : []);
  },
  note(icon, text) { const li = this.turns.findIndex(t => t.live), it = { role: 'tool', icon, content: text }; if (li >= 0) this.turns.splice(li, 0, it); else this.turns.push(it); this.paint(); },
  async send(text) {
    text = text.trim(); if (!text || this.busy) return;
    this.turns.push({ role: 'user', content: text }); this.busy = true; this.paint();
    const sample = await Cap.get('sample');
    if (!sample) { this.offline(text); this.busy = false; this.paint(); return; }
    const limits = await sample.limits().catch(() => null);
    const hist = this.turns.filter(t => t.role !== 'tool').slice(-14);
    while (hist.length && hist[0].role !== 'user') hist.shift();
    const input = [{ role: 'user', content: this.context() }, ...hist.map(t => ({ role: t.role, content: t.content }))];
    const live = { role: 'assistant', content: '', live: true }; this.turns.push(live);
    this.ctl = new AbortController(); this.paint();
    try {
      const opts = { cache: false, signal: this.ctl.signal, onText: ({ text: tx }) => { live.content = tx; this.paintLive(live); } };
      if (limits && limits.tools) { opts.tools = this.tools(); delete opts.cache; }
      const { text: out } = await sample(input, opts);
      live.content = out.replace(/\n{3,}/g, '\n\n').trim();
    } catch (e) {
      if (e && e.text) live.content = e.text;
      else this.turns.splice(this.turns.indexOf(live), 1);
      if (!e || e.code !== 'cancelled') { if (e && (e.code === 'not_granted' || e.code === 'sampling_disabled')) { this.turns.push({ role: 'assistant', content: 'Per usare il segretario serve il permesso di usare Claude da questa pagina. Intanto posso comunque aggiungere eventi e promemoria scritti in modo semplice, come “riunione giovedì alle 18”.' }); Cap._p.sample = Promise.resolve(null); } else aiError(e); }
    }
    delete live.live; this.busy = false; this.ctl = null; this.persist(); App.refresh(); this.paint();
  },
  offline(text) {
    const low = text.toLowerCase();
    if (/\b(oggi|domani)\b.*\?|cosa ho|che impegni|agenda/.test(low)) {
      const k = /domani/.test(low) ? addDK(todayK(), 1) : todayK();
      const its = itemsOn(k), tk = S.tasks.filter(t => !t.done && t.due === k);
      this.turns.push({ role: 'assistant', content: its.length || tk.length ? `${relDay(k, true)}:\n${its.map(x => `• ${x.allDay ? 'Tutto il giorno' : x.s} ${x.title}`).join('\n')}${tk.length ? '\nDa fare:\n' + tk.map(t => '• ' + t.title).join('\n') : ''}` : `${relDay(k, true)} non hai niente in programma.` });
      return;
    }
    const p = parseQuick(text);
    if (p.title && (p.date || p.time)) { commitQuick(p); this.turns.push({ role: 'assistant', content: `Fatto: ${p.kind === 'event' ? 'evento' : 'promemoria'} “${p.title}” per ${relDay(p.date, true).toLowerCase()}${p.time ? ' alle ' + p.time : ''}.` }); App.refresh(); return; }
    this.turns.push({ role: 'assistant', content: 'Qui funziono in modalità semplice: posso aggiungere eventi e promemoria con data (“studio di gruppo venerdì alle 15”) e dirti cosa hai oggi o domani. ' + (window.orbitaDesktop ? 'Collegando un\'intelligenza artificiale (anche gratuita) in Account potrò anche ragionare, pianificare lo studio e rispondere a domande.' : 'Aprendo Orbita nell\'app Claude potrò anche ragionare, pianificare lo studio e rispondere a domande.') });
    this.persist();
  },
  paintLive(live) { const el = $('#liveMsg'); if (el) { el.textContent = live.content; const m = $('#msgs'); m.scrollTop = m.scrollHeight; } else this.paint(); },
  paint() {
    const m = $('#msgs'); if (!m) return;
    m.innerHTML = this.turns.length ? this.turns.map(t => t.role === 'tool' ? `<div class="msg tool">${ico('check', 'sm')}${esc(t.content)}</div>` : t.live && !t.content ? `<div class="msg ai"><span class="typing"><i></i><i></i><i></i></span></div>` : `<div class="msg ${t.role === 'user' ? 'me' : 'ai'}" ${t.live ? 'id="liveMsg"' : ''}>${esc(t.content)}</div>`).join('') : this.hello();
    m.scrollTop = m.scrollHeight;
    const send = $('#chatSend'), stop = $('#chatStop'); if (send) { send.hidden = this.busy; stop.hidden = !this.busy; }
  },
  hello() {
    return `<div class="empty" style="margin:auto;gap:14px"><span class="ai-orb"></span><b style="font-size:22px;letter-spacing:-.02em">Ciao${S.profile.name ? ' ' + esc(S.profile.name) : ''}, sono il tuo segretario</b><p style="max-width:44ch">Conosco la tua agenda, i promemoria, gli esami e gli obiettivi. Chiedimi di organizzare la settimana, trovare tempo per studiare o aggiungere impegni: lo faccio direttamente nell'app.</p></div>`;
  },
  ask(text) { go('assistant'); setTimeout(() => this.send(text), 60); },
};
function mdLite(md) {
  const lines = md.split('\n'); let out = '', list = null;
  const close = () => { if (list) { out += `</ul>`; list = null; } };
  const inl = s => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\*(.+?)\*/g, '<i>$1</i>');
  for (const raw of lines) {
    const l = raw.trimEnd();
    let m;
    if ((m = l.match(/^#{1,3}\s+(.*)/))) { close(); out += `<h2>${inl(m[1])}</h2>`; }
    else if ((m = l.match(/^\s*-\s*\[( |x)\]\s+(.*)/i))) { if (list !== 'cl') { close(); out += '<ul class="cl">'; list = 'cl'; } out += `<li${m[1].toLowerCase() === 'x' ? ' class="on"' : ''}>${inl(m[2])}</li>`; }
    else if ((m = l.match(/^\s*[-•*]\s+(.*)/))) { if (list !== 'ul') { close(); out += '<ul>'; list = 'ul'; } out += `<li>${inl(m[1])}</li>`; }
    else if (!l.trim()) close();
    else { close(); out += `<p>${inl(l)}</p>`; }
  }
  close(); return sanitize(out);
}
VIEWS.assistant = {
  actions: () => `<button class="btn sm" data-act="chatClear">Nuova chat</button>`,
  live() { Assistant.paint(); },
  render() {
    const sugg = ['Cosa ho in programma questa settimana?', 'Trova 3 slot da 2 ore per studiare prima del prossimo esame', 'Aggiungi riunione di squadra giovedì alle 18', 'Fammi un obiettivo per preparare il prossimo esame', 'Organizzami la giornata di domani', 'Creami una playlist Spotify per studiare 50 minuti', 'Ho speso 8 euro per pranzo'];
    return `<div class="chat"><div class="msgs" id="msgs"></div>
      <div class="sugg" id="sugg">${sugg.map(s => `<button class="chip" data-sugg="${esc(s)}">${esc(s)}</button>`).join('')}</div>
      <div class="composer"><textarea id="chatIn" rows="1" placeholder="Scrivi al segretario…" enterkeyhint="send"></textarea><button class="icon-btn" id="chatSend" style="background:var(--accent);color:#fff" aria-label="Invia">${ico('send')}</button><button class="icon-btn" id="chatStop" hidden aria-label="Ferma">${ico('pause')}</button></div></div>`;
  },
  mount(root) {
    const inp = $('#chatIn', root);
    const send = () => { const v = inp.value; inp.value = ''; inp.style.height = ''; Assistant.send(v); };
    inp.addEventListener('input', () => { inp.style.height = 'auto'; inp.style.height = Math.min(140, inp.scrollHeight) + 'px'; });
    inp.addEventListener('keydown', e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send(); } });
    $('#chatSend', root).onclick = send;
    $('#chatStop', root).onclick = () => Assistant.ctl && Assistant.ctl.abort();
    $$('[data-sugg]', root).forEach(b => b.onclick = () => Assistant.send(b.dataset.sugg));
    Assistant.paint();
    if (innerWidth > 900) inp.focus();
  },
};
ACT.chatClear = () => { if (Assistant.busy) return; Assistant.turns = []; Assistant.persist(); Assistant.paint(); };

