    const spId2 = $('#sSpId', root); if (spId2) spId2.addEventListener('change', () => { P.spClientId = spId2.value.trim(); save('profile'); App.render(); });
    const spCopy = $('#sSpCopy', root); if (spCopy) spCopy.onclick = async () => { if (!(await copyText(SPA.redirect()))) Island.toast({ icon: 'copy', t: 'Seleziona e copia l\'indirizzo a mano', ms: 2400 }); };
    const spAuto = $('#sSpAuto', root); if (spAuto) wireToggle(spAuto, on => { P.spAuto = on; save('profile'); });
    const bind = (id, key, num) => { const el = $('#' + id, root); el.addEventListener('change', () => { P[key] = num ? (+el.value || P[key]) : el.value.trim(); save('profile'); App.refreshChrome(); if (key.endsWith('Len') && !Timer.running) Timer.set(Timer.mode, false); }); };
    bind('sName', 'name'); bind('sCourse', 'course'); bind('sCfu', 'totalCfu', true); bind('sTgt', 'targetMedia', true); bind('sF', 'focusLen', true); bind('sB', 'breakLen', true); bind('sL', 'longLen', true);
